	'home_security_founder' => '<li>คุณสามารถกำหนดตำแหน่งทีมงานที่หลากหลายเพื่อมอบหมายให้กับสมาชิกทีมดูแลเว็บไซต์ของคุณ เพื่อให้พวกเขาจัดการงานต่าง ๆ ของเว็บไซต์<li>“<strong>รองผู้ดูแลเว็บ</strong>” มีสิทธิ์ทั้งหมดในส่วนหลัง ยกเว้นสิทธิ์เฉพาะของ “ผู้ก่อตั้ง (ผู้ดูแลเว็บ)” ซึ่งถือเป็นลำดับรองลงมาจาก “ผู้ก่อตั้ง (ผู้ดูแลเว็บ)”</li>',
	'home_security_nofounder' => '<li>คุณยังไม่ได้ตั้งค่า <u>ผู้ก่อตั้งเว็บไซต์</u> ผู้ใช้ทั้งหมดในกลุ่มผู้ดูแลระบบจะสามารถเข้าสู่ศูนย์ดูแลระบบได้ โปรดแก้ไข config/config_global.php เพื่อเพิ่มผู้ก่อตั้ง เพื่อควบคุมขอบเขตสิทธิ์ของสมาชิกทีมงานอย่างมีประสิทธิภาพ',
	'home_security_checkip' => '<li>คุณได้ปิด <u>การตรวจสอบไอพีของผู้ดูแลระบบ</u> แนะนำให้ปิดการตรวจสอบนี้เฉพาะในกรณีที่ผู้ดูแลระบบไม่สามารถเข้าสู่ระบบหลังบ้านได้เท่านั้น คุณสามารถเปิดฟังก์ชันนี้ได้โดยแก้ไขการตั้งค่าที่เกี่ยวข้องใน config/config_global.php',
	'home_security_tpledit' => '<li>คุณได้เปิดฟังก์ชัน <u>แก้ไขเทมเพลตออนไลน์</u> แนะนำให้เปิดเฉพาะเมื่อจำเป็นอย่างยิ่งเท่านั้น โปรดแก้ไข config/config_global.php เพื่อปิดฟังก์ชันนี้',
	'home_security_runquery' => '<li>คุณได้เปิดฟังก์ชัน <u>รันคำสั่ง SQL</u> แนะนำให้เปิดเฉพาะเมื่อจำเป็นอย่างยิ่งเท่านั้น โปรดแก้ไข config/config_global.php เพื่อปิดฟังก์ชันนี้',
