	'setting_access_register_verify_areawhite' => 'รายชื่อพื้นที่ที่ไม่ต้องผ่านการตรวจสอบสมาชิกใหม่',
	'setting_access_register_verify_areawhite_comment' => 'เมื่อผู้ใช้อยู่ในพื้นที่ที่กำหนด จะลงทะเบียนสำเร็จทันทีโดยไม่ต้องผ่านการตรวจสอบ หนึ่งพื้นที่ต่อหนึ่งบรรทัด เช่น "กรุงเทพฯ"(ไม่ต้องใส่เครื่องหมายอัญประกาศ) หากไม่ต้องการตั้งค่าให้เว้นว่างไว้',
	'setting_access_register_verify_ipwhite' => 'รายชื่อไอพีที่ไม่ต้องผ่านการตรวจสอบสมาชิกใหม่',
	'setting_access_register_verify_ipwhite_comment' => 'เมื่อผู้ใช้อยู่ในไอพีที่กำหนด จะลงทะเบียนสำเร็จทันทีโดยไม่ต้องผ่านการตรวจสอบ หนึ่งไอพีต่อหนึ่งบรรทัด สามารถระบุไอพีเต็มหรือระบุเฉพาะช่วงเริ่มต้นได้ เช่น "192.168."(ไม่ต้องใส่เครื่องหมายอัญประกาศ) หากไม่ต้องการตั้งค่าให้เว้นว่างไว้',
