	'setting_access_access_ipaccess' => 'รายชื่อไอพีที่อนุญาตให้เข้าถึงเว็บไซต์',
	'setting_access_access_ipaccess_comment' => 'เฉพาะผู้ใช้ที่มีไอพีในรายการนี้เท่านั้นที่เข้าถึงเว็บไซต์ได้ ไอพีอื่นที่ไม่อยู่ในรายการจะถูกปิดกั้น ฟังก์ชันนี้เหมาะสำหรับใช้ภายในองค์กรหรือสถาบันการศึกษาเท่านั้น ไม่มีข้อยกเว้นสำหรับผู้ดูแลระบบ หากไอพีของผู้ดูแลระบบไม่อยู่ในนี้ก็จะไม่สามารถล็อกอินได้เช่นกัน โปรดใช้งานด้วยความระมัดระวัง สามารถระบุไอพีเต็มหรือช่วงเริ่มต้นได้ เช่น "192.168." เว้นว่างไว้เพื่ออนุญาตทุกไอพี ยกเว้นไอพีที่ถูกแบนโดยเฉพาะ',
