	'setting_access_access_adminipaccess_comment' => 'เฉพาะผู้ใช้ที่มีไอพีในรายการนี้เท่านั้นที่เข้าถึงศูนย์ดูแลระบบได้ ไอพีอื่นจะเข้าส่วนหลังบ้านไม่ได้แต่ยังดูหน้าเว็บปกติได้ โปรดใช้งานด้วยความระมัดระวัง สามารถระบุไอพีเต็มหรือช่วงเริ่มต้นได้ เช่น "192.168." เว้นว่างไว้เพื่อให้ทุกไอพีเข้าถึงได้ (ยกเว้นไอพีที่ถูกแบน)',
