	'setting_domain_base' => 'ตั้งค่าพื้นฐาน',
	'setting_domain_base_tips' => "<li>หลังจากตั้งค่าโดเมนย่อยที่สงวนไว้แล้ว จะไม่มีใครสามารถขอใช้หรือใช้งานโดเมนเหล่านั้นได้</li><li>เมื่อเปิดใช้งานโดเมนย่อยสำหรับสเปซส่วนตัวและวงในแล้ว จำเป็นต้องไปที่ <strong>ตั้งค่าโดเมนหลัก</strong> เพื่อกำหนดโดเมนหลักของ <strong>{$_G['setting']['navs'][3]['navname']} และ {$_G['setting']['navs'][4]['navname']}</strong></li>",
