	'setting_domain_app_domain' => 'โดเมน',
	'setting_domain_app_tips' => '<li>โดเมนที่ผูกไว้ต้องไม่ซ้ำกัน ไม่ต้องเติม “<strong>http://</strong>” และห้ามลงท้ายด้วย “<strong>/</strong>” เช่น portal.discuz.vip</li><li>หากเปิดใช้งานโดเมนใดโดเมนหนึ่ง จำเป็นต้องตั้งค่าโดเมนเริ่มต้น มิฉะนั้นจะเกิดปัญหาการเข้าถึงหลายช่องทาง (Multi-entry)</li><li>เมื่อเปิดใช้งานหลายโดเมน โปรดแก้ไขค่า cookiedomain ในไฟล์ config/config_global.php เพื่อตั้งค่าขอบเขตของ Cookie</li>',
	'setting_domain_app_mobile_tips' => 'เมื่อตั้งค่าโดเมนสำหรับมือถือแล้ว การเข้าถึงผ่านเบราว์เซอร์ที่ไม่ใช่เบราว์เซอร์มือถือจะถูกส่งต่อไปยังโดเมนเริ่มต้นโดยอัตโนมัติ',
	'setting_domain_root' => 'ตั้งค่าโดเมนหลัก',
	'setting_domain_root_tips' => "<li>สามารถตั้งค่าโดเมนหลักสำหรับโดเมนย่อยของ <strong>สเปซส่วนตัว, {$_G['setting']['navs'][3]['navname']}, บอร์ด, หัวข้อพิเศษ และหมวดหมู่บทความ</strong> ได้ ตัวอย่าง: หากต้องการให้ผู้ใช้ขอใช้ XXX.discuz.vip ให้กรอกโดเมนหลักว่า: discuz.vip</li><li>หลังจากตั้งค่าโดเมนหลักสำหรับ <strong>สเปซส่วนตัว และ {$_G['setting']['navs'][3]['navname']}</strong> แล้ว ยังต้องไปเปิดสวิตช์โดเมนย่อยใน <strong>ตั้งค่าพื้นฐาน</strong> ผู้ใช้จึงจะสามารถขอผูกโดเมนย่อยได้ ทั้งนี้ขึ้นอยู่กับการจำกัดความยาวโดเมนย่อยของแต่ละกลุ่มผู้ใช้งานด้วย</li><li>สำหรับการเปิดใช้งานโดเมนย่อยของ <strong>หมวดหมู่บทความ</strong> หากเป็นการผูกกับไดเรกทอรี คุณจำเป็นต้องตั้งค่าการผูกโดเมนในสภาพแวดล้อมเซิร์ฟเวอร์ด้วยตนเอง</li><li>ไม่แนะนำให้เปลี่ยนโดเมนหลักที่ต่างกันให้เป็นโดเมนหลักเดียวกันในภายหลัง</li>",
