	'setting_seo_portal' => 'หน้าแรกพอร์ทัล',
	'setting_seo_global_tips' => '<li>ตัวแปรที่แทรกต้องอยู่ในเครื่องหมายปีกกา “{}” เสมอ หากตัวแปรนั้นไม่รองรับในขอบเขตที่ใช้งาน ตัวแปรจะถูกซ่อนไว้ในหน้าเว็บ (รวมถึงเครื่องหมายคั่นหลังตัวแปรด้วย) หากเว้นว่างไว้จะใช้ค่าเริ่มต้นของระบบ ทั้งนี้รองรับการเขียน SEO ด้วยตนเอง</li><li>ตัวแปร SEO ที่ใช้งานได้มีดังนี้:&nbsp;<br></li>',
	'setting_seo_portal_tips' => '<li>ชื่อเว็บไซต์&nbsp;<font class="highlight">{bbname}</font> (ใช้ได้ทุกตำแหน่ง)</li><li>ชื่อหมวดหมู่ปัจจุบัน&nbsp;<font class="highlight">{curcat}</font> (ใช้ได้ทุกตำแหน่ง ยกเว้นหน้าแรก)</li><li>ชื่อหมวดหมู่หลัก&nbsp;<font class="highlight">{firstcat}</font> (ใช้ได้ทุกตำแหน่ง ยกเว้นหน้าแรก)</li><li>ชื่อหมวดหมู่ย่อย&nbsp;<font class="highlight">{secondcat}</font> (ใช้ได้ทุกตำแหน่ง ยกเว้นหน้าแรก)</li><li>ชื่อบทความ&nbsp;<font class="highlight">{subject}</font> (ใช้ได้เฉพาะหน้าเนื้อหาบทความ)</li><li>เนื้อหาบทความย่อ&nbsp;<font class="highlight">{summary}</font> (ใช้ได้เฉพาะหน้าเนื้อหาบทความ)</li><li>ผู้เขียนบทความ&nbsp;<font class="highlight">{user}</font> (ใช้ได้เฉพาะหน้าเนื้อหาบทความ)</li><li>เลขหน้า&nbsp;<font class="highlight">{page}</font> (ใช้ได้ในหน้าบทความและเนื้อหาบทความ)</li>',
