	'setting_seo_forum' => 'หน้าแรกเว็บบอร์ด',
	'setting_seo_forum_tips' => '<li>ชื่อเว็บไซต์&nbsp;<font class="highlight">{bbname}</font> (ใช้ได้ทุกตำแหน่ง)</li><li>ชื่อบอร์ดปัจจุบัน&nbsp;<font class="highlight">{forum}</font> (ใช้ได้ทุกตำแหน่ง ยกเว้นหน้าแรก)</li><li>ชื่อบอร์ดหลัก&nbsp;<font class="highlight">{fup}</font> (ใช้ได้ในหน้ารายการกระทู้บอร์ดย่อยและหน้าเนื้อหากระทู้)</li><li>ชื่อโซนเว็บบอร์ด&nbsp;<font class="highlight">{fgroup}</font> (ใช้ได้ทุกตำแหน่ง ยกเว้นหน้าแรก)</li><li>หัวข้อกระทู้&nbsp;<font class="highlight">{subject}</font> (ใช้ได้เฉพาะหน้าเนื้อหากระทู้)</li><li>เนื้อหากระทู้ย่อ&nbsp;<font class="highlight">{summary}</font> (ใช้ได้เฉพาะหน้าเนื้อหากระทู้)</li><li>แท็กกระทู้&nbsp;<font class="highlight">{tags}</font> (ใช้ได้เฉพาะหน้าเนื้อหากระทู้)</li><li>เลขหน้า&nbsp;<font class="highlight">{page}</font> (ใช้ได้ในหน้ารายการกระทู้และเนื้อหากระทู้)</li>',
