	'setting_cachethread_coefficient_comment' => 'ฟังก์ชันแคชหน้าเว็บจะช่วยเก็บข้อมูลกระทู้ที่มีสมาชิกเข้าชมบ่อยไว้ชั่วคราว เพื่อช่วยลดภาระของเซิร์ฟเวอร์ขนาดใหญ่ ช่วงค่าสัมประสิทธิ์คือ 0 - 100 แนะนำให้ตั้งไว้ที่ 40 ตั้งเป็น 0 เพื่อปิด หากพื้นที่ดิสก์เพียงพอ การเพิ่มค่านี้จะช่วยให้การแคชมีประสิทธิภาพมากขึ้น',
