	'setting_avatar' => 'ตั้งค่ารูปโปรไฟล์',

	'setting_memory' => 'เพิ่มประสิทธิภาพหน่วยความจำ',
	'setting_memory_tips' => '<li>การเปิดใช้งานฟังก์ชันเพิ่มประสิทธิภาพหน่วยความจำจะช่วยเพิ่มประสิทธิภาพของโปรแกรมและขีดความสามารถในการรองรับภาระของเซิร์ฟเวอร์ได้อย่างมาก โดยฟังก์ชันนี้ต้องการการรองรับจากระบบเซิร์ฟเวอร์และมอดูลส่วนขยายของ PHP</li><li>อินเทอร์เฟซหน่วยความจำที่รองรับในปัจจุบัน ได้แก่ Memcache, eAccelerator, Alternative PHP Cache (APC), Xcache, Redis, YAC และ APCu โดยระบบจะเลือกใช้อินเทอร์เฟซตามสภาพแวดล้อมของเซิร์ฟเวอร์โดยอัตโนมัติ</li><li>การตั้งค่าหลักของอินเทอร์เฟซหน่วยความจำจะอยู่ในไฟล์ config_global.php ซึ่งคุณสามารถแก้ไขไฟล์ดังกล่าวเพื่อตั้งค่าขั้นสูงได้</li>',
