	'setting_serveropti_jspath' => 'URL ของไฟล์ JS',
	'setting_serveropti_jspath_comment' => 'ตั้งค่า URL สำหรับไฟล์ JS ของเว็บไซต์ เมื่อตั้งค่าเป็นไดเรกทอรีแคช ระบบจะบีบอัดไฟล์ *.js จากไดเรกทอรีระบบและบันทึกไว้ในไดเรกทอรีแคชเพื่อเพิ่มความเร็วในการอ่านและเข้าถึงของผู้ใช้',
