	'setting_serveropti_searchctrl_comment' => 'หากค้นหาซ้ำในเวลาน้อยกว่าที่กำหนดจะถูกระงับ ตั้งเป็น 0 เพื่อไม่จำกัด',
	'setting_serveropti_maxspm' => '<span class="spectitle">จำนวนการค้นหาสูงสุดต่อ 60 วินาที</u></i>',
	'setting_serveropti_maxspm_comment' => 'จำนวนการค้นหาสูงสุดที่ระบบตอบสนองในทุก ๆ 60 วินาที ตั้งเป็น 0 เพื่อไม่จำกัด หมายเหตุ: หากเซิร์ฟเวอร์มีภาระงานหนัก แนะนำให้ตั้งไว้ที่ 5 หรือในช่วง 5 - 20 เพื่อป้องกันการล็อกตารางฐานข้อมูลจากการค้นหาที่ถี่เกินไป',
