	'setting_serveropti_gzipcompress_disabled' => 'พื้นที่ของคุณไม่รองรับมอดูล Zlib จึงไม่สามารถเปิดใช้งานฟังก์ชันนี้ได้',
	'setting_serveropti_optimize_thread_view' => 'เพิ่มประสิทธิภาพการอัปเดตยอดการเข้าชมกระทู้',
	'setting_serveropti_preventrefresh' => '<span class="spectitle">ป้องกันการรีเฟรชยอดการเข้าชม</span>',
	'setting_serveropti_preventrefresh_comment' => 'หากเลือก “ไม่” ยอดการเข้าชมจะเพิ่มขึ้น 1 ทุกครั้งที่มีการเข้าถึงกระทู้ สเปซ หรือไดอารี่ ซึ่งจะเพิ่มภาระให้เซิร์ฟเวอร์ แนะนำให้เลือก “ใช่”',
	'setting_serveropti_delayviewcount' => '<span class="spectitle">หน่วงเวลาการอัปเดตยอดการดาวน์โหลดไฟล์แนบ</span>',
