	'setting_serveropti_delayviewcount_comment' => 'การหน่วงเวลาอัปเดตยอดดาวน์โหลดจะช่วยลดภาระเซิร์ฟเวอร์ได้อย่างมากสำหรับเว็บไซต์ที่มีการเข้าชมสูง แนะนำให้เปิดใช้งานฟังก์ชันนี้',
