	'setting_serveropti_lazyload' => 'เปิดใช้งานการโหลดรูปภาพเมื่อเลื่อนมาถึง (Lazy Load)',
	'setting_serveropti_lazyload_comment' => 'เมื่อเปิดใช้งาน รูปภาพจะถูกโหลดเมื่ออยู่ในหน้าต่างเบราว์เซอร์ปัจจุบันเท่านั้น ช่วยลดภาระเซิร์ฟเวอร์สำหรับเว็บไซต์ที่มีการเข้าชมสูง แนะนำให้เปิดใช้งานฟังก์ชันนี้',
