	'setting_mail_seccode_tips' => '<li>ฟังก์ชัน <strong>รหัสยืนยันทางอีเมล</strong> มีลักษณะคล้ายกับ <strong>รหัสยืนยันทาง SMS</strong> โดยระบบจะส่งรหัสสุ่มที่เป็น ตัวอักษร/ตัวเลข ไปยังอีเมลหลักที่ผู้ใช้ตั้งค่าไว้เพื่อใช้ในการยืนยันตัวตน</li><li>ปัจจุบันฟังก์ชัน <strong>รหัสยืนยันทางอีเมล</strong> ใช้สำหรับขั้นตอนการยืนยันตัวตนในการจัดการบัญชีเป็นหลัก</li>',


	'setting_sec' => 'ตั้งค่าพื้นฐาน',
	'setting_seccheck' => 'ตั้งค่าการตรวจสอบ',
	'setting_accountguard' => 'ปกป้องบัญชี',
	'setting_sec_code_tips' => '<li>กรณีใช้รูปภาพเป็นตัวอักษรรหัสยืนยัน รูปภาพต้องประกอบด้วยตัวอักษร “2346789BCEFGHJKMPQRTVWXY” รวม 24 ตัว และต้องเป็นไฟล์ GIF แบบโปร่งใส พื้นหลังโปร่งใส ตัวอักษรสีดำ โดยสีดำต้องเป็นดัชนีสีแรกของรูปภาพ ไม่จำกัดขนาดรูปภาพ แต่แนะนำให้มีความกว้างไม่เกิน 1/4 ของความกว้างรหัสยืนยัน และความสูงไม่เกินความสูงของรหัสยืนยัน เมื่อสร้างเสร็จแล้วให้สร้างโฟลเดอร์ใหม่ภายใต้ source/data/seccode/gif/ แล้วอัปโหลดไฟล์ GIF ทั้ง 24 ไฟล์ลงไป</li><li>กรณีใช้รูปภาพเป็นพื้นหลังรหัสยืนยัน ให้อัปโหลดไฟล์ JPG ที่เตรียมไว้ไปยัง source/data/seccode/background/ ระบบจะสุ่มเลือกรูปภาพเหล่านั้นมาเป็นพื้นหลัง</li><li>กรณีใช้ฟอนต์ TTF เป็นตัวอักษรรหัสยืนยัน ให้อัปโหลดไฟล์ฟอนต์ภาษาอังกฤษไปยัง source/data/seccode/font/en/ ระบบจะสุ่มเลือกฟอนต์เหล่านั้นมาใช้งาน</li><li>ก่อนใช้งานรหัสยืนยันภาษาจีน ต้องอัปโหลดไฟล์ฟอนต์ TTF ภาษาจีนที่สมบูรณ์ไปยัง source/data/seccode/font/ch/ ก่อน</li><li>รหัสยืนยันของระบบอยู่ที่ source/class/seccode/ ส่วนของปลลักอินอยู่ที่ source/plugin/ชื่อปลั๊กอิน/seccode/</li>',
	'setting_sec_qaa_tips' => '<li>คำถามยืนยันตัวตนควรสั้น กระชับ และไม่มีความหมายกำกวม เพื่อให้คนปกติสามารถตอบได้ถูกต้อง โปรดเปลี่ยนคำถามและคำตอบอยู่เสมอเพื่อป้องกันการเดาทาง</li><li>ส่วนประกอบความปลอดภัยของระบบอยู่ที่ source/class/secqaa/ ของปลั๊กอินอยู่ที่ source/plugin/ชื่อปลั๊กอิน/secqaa/ และส่วนการตรวจสอบของปลั๊กอินอยู่ที่ source/plugin/ชื่อปลั๊กอิน/seccheck/</li><li>ส่วนประกอบความปลอดภัยใหม่จำเป็นต้องเปิดใช้งานระบบแคชหน่วยความจำ (เช่น Redis) โปรดตั้งค่าให้เรียบร้อย</li><li>นักพัฒนาปลั๊กอินโปรดอ่านรายละเอียดใน “<a href="https://open.dismall.com/?!devdoc" target="_blank">เอกสารทางเทคนิค Discuz!</a>” ก่อนออกแบบสคริปต์คำถามยืนยันตัวตนใหม่</li>',

