	'setting_datetime_periods' => 'ตั้งค่าช่วงเวลา',
	'setting_datetime_visitbanperiods' => 'ช่วงเวลาที่ห้ามเข้าชมเว็บไซต์',
	'setting_datetime_visitbanperiods_comment' => 'กำหนดช่วงเวลาในแต่ละวันที่ผู้ใช้ไม่สามารถเข้าชมเว็บไซต์ได้ โปรดใช้รูปแบบเวลา 24 ชั่วโมง หนึ่งช่วงเวลาต่อหนึ่งบรรทัด สามารถระบุช่วงเวลาข้ามคืนได้ หากเว้นว่างไว้จะไม่จำกัด ตัวอย่าง:<br />ตั้งแต่เวลา 23:25 น. ถึง 05:05 น. ของวันถัดไป ให้ระบุ: <i>23:25-5:05</i><br />ตั้งแต่เวลา 09:00 น. ถึง 14:30 น. ในวันเดียวกัน ให้ระบุ: <i>9:00-14:30</i><br />ข้อควรระวัง: รูปแบบที่ไม่ถูกต้องอาจส่งผลต่อการทำงานของระบบได้ หากกลุ่มผู้ใช้งานได้รับสิทธิ์ “ไม่ถูกจำกัดโดยช่วงเวลา” กลุ่มนั้นจะไม่ได้รับผลกระทบจากส่วนนี้ การตั้งค่าช่วงเวลาทั้งหมดจะยึดตามเขตเวลาของระบบเป็นหลัก ไม่ขึ้นกับเขตเวลาส่วนตัวของผู้ใช้',
	'setting_datetime_postbanperiods' => 'ช่วงเวลาที่ห้ามโพสต์เนื้อหา',
	'setting_datetime_postbanperiods_comment' => 'กำหนดช่วงเวลาในแต่ละวันที่ผู้ใช้ไม่สามารถโพสต์เนื้อหาได้ โปรดใช้รูปแบบเวลา 24 ชั่วโมง หนึ่งช่วงเวลาต่อหนึ่งบรรทัด สามารถระบุช่วงเวลาข้ามคืนได้ หากเว้นว่างไว้จะไม่จำกัด ตัวอย่างและข้อควรระวังเช่นเดียวกับหัวข้อด้านบน',
