	'setting_datetime_postmodperiods_comment' => 'กำหนดช่วงเวลาในแต่ละวันที่โพสต์ของผู้ใช้จะไม่แสดงผลทันที แต่ต้องรอให้ผู้ดูแลตรวจสอบก่อน รูปแบบและวิธีการใช้งานเช่นเดียวกับหัวข้อด้านบน',
