	'setting_datetime_postignorearea_comment' => 'เมื่อผู้ใช้อยู่ในพื้นที่ที่กำหนด จะสามารถโพสต์เนื้อหาได้โดยไม่ถูกจำกัดด้วยช่วงเวลา กรอกหนึ่งพื้นที่ต่อหนึ่งบรรทัด เช่น "กรุงเทพฯ" หากต้องการให้ระบบระบุไอพีได้แม่นยำ โปรดอัปโหลดไฟล์ฐานข้อมูลไอพี qqwry.dat ไปที่ source/data/ip/ และเปลี่ยนชื่อเป็น wry.dat',
