	'settings_sphinx_sphinxrank' => 'โหมดการให้คะแนนดัชนีเนื้อหา',
	'settings_sphinx_sphinxrank_comment' => '(1) SPH_RANK_PROXIMITY_BM25: โหมดเริ่มต้น ใช้ทั้งการให้คะแนนตามความใกล้เคียงของวลีและ BM25 ร่วมกัน [แนะนำ]
<br />(2) SPH_RANK_BM25: โหมดคำนวณความเกี่ยวข้องทางสถิติ ใช้เฉพาะ BM25 เท่านั้น (เหมือนเครื่องมือค้นหาส่วนใหญ่) โหมดนี้ทำงานเร็ว แต่อาจทำให้คุณภาพผลลัพธ์ลดลงสำหรับคำค้นหาที่มีหลายคำ
<br />(3) SPH_RANK_NONE: ปิดการให้คะแนน เป็นโหมดที่เร็วที่สุด ผลลัพธ์ที่ตรงกันทั้งหมดจะมีน้ำหนักเท่ากับ 1 เหมือนการค้นหาแบบบูลีน',

