	'setting_antitheft' => 'ตั้งค่าป้องกันการคัดลอกข้อมูล',
	'setting_antitheft_tips' => '<li>ฟังก์ชันป้องกันการคัดลอกข้อมูลไม่มีผลกระทบต่อการเข้าชมของผู้ใช้งานปกติ</li><li>ช่วยป้องกันกระทู้ บทความ และไดอารี่ของเว็บไซต์ไม่ให้ถูกโปรแกรมดูดข้อมูลไปใช้อย่างผิดกฎหมาย</li><li><font style="color:red">หากไอพีเดียวกันปรากฏทั้งในไวท์ลิสต์และแบล็คลิสต์ ระบบจะให้ความสำคัญกับไวท์ลิสต์ก่อน</font></li><li>หลังจากเปิดใช้งานฟังก์ชันนี้ ฟังก์ชันดูตัวอย่างโพสต์ในหน้ารายการกระทู้จะไม่สามารถใช้งานได้</li>',
