	'setting_uc_activation' => 'อนุญาตให้สมาชิกจากแอปอื่นมาเปิดใช้งานในเว็บไซต์นี้หรือไม่',
	'setting_uc_activation_comment' => 'หากเลือก “ใช่” จะอนุญาตให้สมาชิกจากแอปอื่นในเครือข่าย UCenter เข้ามาเปิดใช้งานบัญชีในเว็บไซต์นี้ได้ หากเลือก “ไม่” จะไม่อนุญาตการเปิดใช้งานจากแอปภายนอก',
	'setting_uc_fastactivation' => 'อนุญาตให้เปิดใช้งานโดยตรงหรือไม่',
	'setting_uc_fastactivation_comment' => 'หากเลือก “ใช่” เมื่อผู้ใช้ล็อกอิน ระบบจะเปิดใช้งานบัญชีให้โดยอัตโนมัติ หากเลือก “ไม่” ผู้ใช้จะสามารถเปิดใช้งานได้แต่ต้องกรอกข้อมูลจำเป็นตามที่ตั้งค่าไว้ในส่วนการลงทะเบียน',
	'setting_uc_avatarmethod' => 'วิธีการเรียกใช้รูปโปรไฟล์',
	'setting_uc_avatarmethod_comment' => 'ตั้งค่าวิธีการดึงข้อมูลรูปโปรไฟล์ผู้ใช้
		<br />แบบไดนามิก: พึ่งพาเซิร์ฟเวอร์ในการส่งที่อยู่รูปโปรไฟล์กลับมา หากมีรูปจำนวนมากอาจเพิ่มภาระให้กับเซิร์ฟเวอร์
		<br />แบบสเตติก: ส่งที่อยู่สเตติกของรูปโปรไฟล์กลับมาโดยไม่ตรวจสอบว่ารูปมีอยู่จริงหรือไม่ หากดึงข้อมูลไม่สำเร็จจะแสดงรูปเริ่มต้น
		<br />แบบโหลดผ่านเบราว์เซอร์: ให้เบราว์เซอร์โหลดรูปจากที่อยู่สเตติก หากไม่สำเร็จจะดึงรูปเริ่มต้นมาแสดงให้อัตโนมัติ',
	'setting_uc_avatarmethod_0' => 'เรียกใช้รูปโปรไฟล์แบบไดนามิก',
	'setting_uc_avatarmethod_1' => 'เรียกใช้รูปโปรไฟล์แบบสเตติก',
	'setting_uc_avatarmethod_2' => 'เรียกใช้รูปโปรไฟล์ผ่านเบราว์เซอร์',
	'setting_uc_dynavt' => 'กลไกแคชรูปโปรไฟล์',
