	'forums_edit_perm_tips' => '<li>1. เงื่อนไขต่าง ๆ ภายในประเภทสิทธิ์เดียวกัน (เช่น กลุ่ม, การยืนยันตัวตน) จะมีความสัมพันธ์แบบ "หรือ" (OR)</li>
<li>2. เมื่อมีการตั้งค่า "นิพจน์เงื่อนไขสิทธิ์" สำหรับฟังก์ชันใดฟังก์ชันหนึ่ง (เช่น การเข้าชมบอร์ด, การตั้งกระทู้ใหม่) ระบบจะยึดตามนิพจน์นั้นเป็นหลัก และรายการที่เลือกไว้ด้านบนจะไม่มีผล</li>
<li>3. ภายในประเภทสิทธิ์เดียวกันของฟังก์ชันนั้น ๆ หากเลือกหลายเงื่อนไข ระบบจะถือว่าเป็นความสัมพันธ์แบบ "หรือ" คือเข้าเงื่อนไขใดเงื่อนไขหนึ่งก็ถือว่าผ่าน หากต้องการให้ต้องผ่านทุกเงื่อนไขที่เลือก โปรดเลือกตัวเลือก "ต้องครบทุกเงื่อนไข" ด้านล่าง</li>
<li>4. สำหรับการตรวจสอบเงื่อนไขที่ซับซ้อนกว่านั้น เช่น การตรวจสอบข้ามประเภทสิทธิ์ หรือการใช้ and และ or ร่วมกัน โปรดใช้ "นิพจน์เงื่อนไขสิทธิ์" ในการเขียนกฎ</li>',
