	'forums_edit_posts_attach_ext_comment' => 'ระบุนามสกุลไฟล์แนบที่อนุญาตให้อัปโหลด แยกหลายรายการด้วยเครื่องหมายจุลภาค “,” การตั้งค่านี้จะมีความสำคัญสูงกว่าสิทธิ์ในกลุ่มผู้ใช้งาน หากเว้นว่างไว้จะยึดตามค่าที่กำหนดในกลุ่มผู้ใช้งาน',
