	'forums_edit_posts_allowfeed_default_comment' => 'หากเปิดใช้งาน ช่องเลือก “ส่งสเตตัส” จะถูกติ๊กไว้ล่วงหน้า ผู้ใช้สามารถติ๊กออกเองได้ มิฉะนั้นจะเป็นเพียงการเปิดสิทธิ์ให้เลือกแต่ไม่ได้ติ๊กไว้ให้แต่แรก',
	'forums_edit_posts_commentitem' => 'ความคิดเห็นสำเร็จรูปสำหรับกระทู้ทั่วไป',
	'forums_edit_posts_commentitem_comment' => 'กรอกหนึ่งความคิดเห็นต่อบรรทัด บรรทัดว่างจะใช้แยกรายการที่จะแสดงในเมนูเลือก ฟังก์ชันนี้จะมีผลเมื่อเปิดใช้งานการให้เรตติ้งความคิดเห็นแล้วเท่านั้น หากเว้นว่างไว้จะใช้ค่าจาก “ความคิดเห็นสำเร็จรูปสำหรับกระทู้ทั่วไป” ของส่วนกลาง',
