	'forums_edit_posts_noforumrecommend_comment' => 'สามารถเลือกปิดฟังก์ชันแนะนำการตอบกลับเฉพาะบอร์ดนี้ได้ เหมาะสำหรับบอร์ดที่เน้นการคุยเล่นทั่วไป',

	'forums_edit_attachtype' => 'ประเภทไฟล์แนบ',
	'forums_edit_attachtype_tips' => '<li>ฟังก์ชันนี้ใช้กำหนดขนาดสูงสุดของไฟล์แนบเฉพาะประเภทในบอร์ดนี้ หากขนาดที่ระบุไว้ที่นี่เล็กกว่าที่กลุ่มผู้ใช้งานได้รับสิทธิ์ ระบบจะยึดตามค่าในบอร์ดนี้เป็นหลัก</li><li>คุณสามารถตั้งขนาดสูงสุดเป็น 0 เพื่อห้ามอัปโหลดไฟล์ประเภทนั้น ๆ ทั้งหมดในบอร์ดนี้</li><li>หากเว้นว่างไว้จะยึดตามค่าเริ่มต้นจากส่วนกลางในเมนู “ประเภทและขนาดไฟล์แนบ”</li>',

	'forums_edit_credits' => 'นโยบายเครดิต',
