	'forums_edit_credits_comment' => 'ช่วงการเพิ่มหรือลดเครดิตแต่ละรายการอยู่ที่ -99 ถึง +99 ตัวเลขในวงเล็บคือค่าที่ตั้งไว้ในนโยบายเครดิตส่วนกลาง <a href="home.php?mod=spacecp&ac=credit&op=rule&fid={fid}" target="_blank">ดูคำอธิบายเกณฑ์เครดิตของบอร์ดนี้</a>',

	'forums_edit_threadtypes' => 'หมวดหมู่กระทู้',
	'forums_edit_threadtypes_comment' => 'คุณสามารถเปิดใช้งานหมวดหมู่กระทู้ที่มีอยู่หรือเพิ่มหมวดหมู่ใหม่สำหรับบอร์ดนี้ได้ หากมีหมวดหมู่จำนวนมาก แนะนำให้ตั้งค่าแสดงผลแบบ “เรียงปกติ” เฉพาะหมวดหมู่ที่สำคัญ ส่วนที่เหลือให้แสดงแบบ “เมนูเลื่อนลง” แทน',
	'forums_edit_threadtypes_config' => 'หมวดหมู่กระทู้',
	'forums_edit_threadtypes_tips' => '<ul><li>“หมวดหมู่กระทู้” ใช้สำหรับจัดกลุ่มกระทู้ภายในบอร์ด เมื่อสมาชิกสร้างกระทู้ใหม่จะสามารถเลือกประเภทตามที่กำหนดไว้ได้ และผู้ใช้คนอื่นยังสามารถเลือกดูตามหมวดหมู่ได้ (ต้องตั้งค่าใน “แก้ไขบอร์ด”) สิ่งที่ต่างจากบอร์ดย่อยคือ หมวดหมู่กระทู้มีไว้เพื่อจัดกลุ่มเนื้อหาที่มีความเกี่ยวข้องกันสูงแต่ยังต้องการความชัดเจนในประเภทข้อมูล</li></ul><ul><li>“หมวดหมู่กระทู้” เป็นข้อมูลที่ใช้ร่วมกันทั้งเว็บไซต์ โดยคุณสามารถเลือกใช้บางหมวดหมู่ให้เหมาะสมกับแต่ละบอร์ดได้ในหน้า “แก้ไขบอร์ด”</li></ul><ul><li>หากมีการเปลี่ยนชื่อ ลบ หรือแก้ไขลำดับของหมวดหมู่กระทู้ โปรดเข้าไปที่บอร์ดที่เกี่ยวข้องกับหมวดหมู่นั้น (ไม่ต้องแก้ไขข้อมูลใด ๆ) แล้วกดส่งข้อมูลเพื่อให้การแสดงผลอัปเดตตามที่แก้ไข</li></ul>',
	'forums_edit_threadtypes_name' => 'ชื่อหมวดหมู่',
