	'threadtype_infotypes_template_tips' => '<li>หากเทมเพลตว่างเปล่า ระบบจะใช้เทมเพลตเริ่มต้นของระบบ</li><li>คลิกที่ลิงก์ [แทรกลงเทมเพลต] ด้านบนเพื่อใส่โค้ดที่เกี่ยวข้อง จากนั้นคุณสามารถแก้ไขด้วยโปรแกรมแก้ไขอย่าง DreamWeaver หรือแก้ไขด้วยตนเองได้</li><li>เทมเพลตการแสดงผลรองรับ HTML โดยที่ {ชื่อตัวแปรฟิลด์} แทนชื่อของฟิลด์นั้น และ [ชื่อตัวแปรฟิลด์] แทนค่าที่กรอกลงในฟิลด์<br />ตัวอย่างเช่น: มีฟิลด์ชื่อ age (อายุ) และสมาชิกกรอกค่าเป็น 20 หากใช้สตริง {age} [agevalue] ในเทมเพลต จะแสดงผลเป็น อายุ 20</li>',
	'threadtype_infotypes_validity' => 'ตั้งค่าระยะเวลาที่มีผลหรือไม่',
	'threadtype_infotypes_validity_comment' => 'กำหนดว่าหมวดหมู่ข้อมูลนี้มีการจำกัดระยะเวลาหรือไม่ หากหมดอายุข้อมูลจะไม่ถูกนำไปรวมในการค้นหา โดยระยะเวลานี้ผู้ใช้จะเลือกเองในขณะโพสต์',
	'threadtype_super' => 'หมวดหมู่ข้อมูลระดับสูง',
	'threadtype_supertpl_forumdisplay' => 'เทมเพลตหน้ารายการกระทู้',
	'threadtype_supertpl_forumdisplay_comment' => 'ไฟล์เทมเพลตที่จะใช้ในหน้ารายการกระทู้เมื่อบอร์ดเปิดโหมด “สไตล์หมวดหมู่ข้อมูลระดับสูง” สามารถใช้ค่า “forum/super_forumdisplay” ซึ่งเป็นตัวอย่างมาตรฐาน หรือใช้รูปแบบ “pluginid:filename” เพื่อเรียกใช้เทมเพลตจากปลั๊กอิน',
	'threadtype_supertpl_viewthread' => 'เทมเพลตหน้าเนื้อหากระทู้',
