	'threadtype_tips' => '<li>การแก้ไขส่วนนี้จำเป็นต้องมีความรู้พื้นฐานด้าน HTML และ CSS โปรดแก้ไขด้วยความระมัดระวัง</li><li>รหัส “[file]filename[/file]” ใช้เรียกไฟล์ template/default/<u>filename</u>.php และรหัส “[file]pluginid:filename[/file]” ใช้เรียกไฟล์เทมเพลตจากปลั๊กอินที่ source/plugin/<u>pluginid</u>/template/<u>filename</u>.php ทั้งนี้รองรับเทมเพลตสำหรับมือถือในโฟลเดอร์ touch ด้วย</li>',
