	'threadtype_edit_select_choices' => 'ข้อมูลในฟิลด์',
	'threadtype_edit_select_choices_comment' => 'ใช้ได้เฉพาะฟิลด์ประเภทตัวเลือกเท่านั้น กรอกหนึ่งรายการต่อบรรทัด โดยใส่ดัชนี (แนะนำให้ใช้ตัวเลข) ไว้หน้าเครื่องหมายเท่ากับ ตัวอย่างเช่น: <br /><i>1 = เมาส์ออปติคัล<br />2 = เมาส์แบบกลไก<br />3 = ไม่มีเมาส์</i><br /><i>1.1 = เมาส์ออปติคัลสีดำ</i><br /><i>1.2 = เมาส์ออปติคัลสีแดง</i><br /><i>1.2.1 = เมาส์ออปติคัลบลูทูธสีแดง</i><br />หมายเหตุ: <br />1. รายการย่อยเช่น "1.2.1" ต้องมีรายการหลัก "1.2" และ "1" อยู่ด้วยเสมอ<br />2. ห้ามเว้นวรรคภายในชุดตัวเลขดัชนี เช่น "1.2.1"<br />3. เมื่อกำหนดแล้วไม่ควรเปลี่ยนความสัมพันธ์ระหว่างดัชนีและชื่อรายการ แต่สามารถเพิ่มรายการใหม่ได้ หากต้องการเปลี่ยนลำดับให้ใช้วิธีสลับบรรทัดแทน',
	'threadtype_edit_choices' => 'ข้อมูลในฟิลด์',
	'threadtype_edit_choices_comment' => 'ใช้ได้เฉพาะฟิลด์ประเภทตัวเลือกเท่านั้น กรอกหนึ่งรายการต่อบรรทัด โดยใส่ดัชนี (แนะนำให้ใช้ตัวเลข) ไว้หน้าเครื่องหมายเท่ากับ ตัวอย่างเช่น: <br /><i>1 = เมาส์ออปติคัล<br />2 = เมาส์แบบกลไก<br />3 = ไม่มีเมาส์</i><br />หมายเหตุ: เมื่อกำหนดแล้วไม่ควรเปลี่ยนความสัมพันธ์ระหว่างดัชนีและชื่อรายการ แต่สามารถเพิ่มรายการใหม่ได้ หากต้องการเปลี่ยนลำดับให้ใช้วิธีสลับบรรทัดแทน',
