	'templates_add_tips' => '<li><b>ฟังก์ชันนี้สำหรับนักพัฒนาเทมเพลตเท่านั้น</b></li><li>นักพัฒนาเทมเพลตโปรดอ่านเนื้อหาใน “<a href="https://open.dismall.com/?!devdoc" target="_blank">เอกสารทางเทคนิค Discuz!</a>” ก่อนใช้งานฟังก์ชันนี้</li><li>คำเตือน: การออกแบบหรือติดตั้งเทมเพลตที่ไม่ถูกต้องอาจส่งผลกระทบต่อการใช้งานเว็บไซต์ทั้งหมด</li>',
