	'templates_maint_default_comment' => '<li>คุณกำลังแก้ไขเทมเพลตเริ่มต้น เพื่อความสะดวกในการขยายไปยังเทมเพลตอื่น ขอแนะนำอย่างยิ่งว่าไม่ควรแก้ไขเนื้อหาในเทมเพลตเริ่มต้นโดยตรง</li><li>หากต้องการแก้ไข โปรดคัดลอกไฟล์เทมเพลตไปยังไดเรกทอรีเทมเพลตอื่นก่อนทำการแก้ไข</li>',
	'templates_maint_nondefault_comment' => '<li>เทมเพลตในชุดนี้ไม่จำเป็นต้องมีครบทุกไฟล์ ไฟล์ที่ขาดหายไปจะถูกแทนที่ด้วยเทมเพลตเริ่มต้นโดยอัตโนมัติ</li><li>หากชื่อเทมเพลตแสดงเป็น <font color="#FF0000">สีแดง</font> หมายถึงไฟล์นี้มีความแตกต่างจากเทมเพลตเริ่มต้น หากแสดงเป็น <font color="#00FF00">สีเขียว</font> หมายถึงเป็นไฟล์เทมเพลตที่ผู้ใช้เพิ่มเข้าไปเองซึ่งไม่มีอยู่ในเทมเพลตเริ่มต้น</li><li>หากคุณต้องการเผยแพร่เทมเพลตชุดนี้ แนะนำให้ลบไฟล์ที่เหมือนกับเทมเพลตเริ่มต้นออกก่อนทำการเผยแพร่</li>',
