	'members_export_tips' => '<li>ชื่อกลุ่มผู้ใช้งานที่เป็นตัวหนาคือกลุ่มระบบ ตัวเอียงคือกกลุ่มที่กำหนดเอง และตัวปกติคือกลุ่มสมาชิกทั่วไป</li><li>การส่งออกข้อมูลผู้ใช้รองรับสูงสุด 10,000 รายการ ไฟล์ที่ส่งออกสามารถเปิดได้ด้วย EXCEL, WPS หรือเครื่องมือจัดการเอกสารออนไลน์อื่น ๆ</li>',

