	'members_newsletter_mobile_tips' => '<li>คุณสามารถส่งการแจ้งเตือนไปยังผู้ใช้แอปพลิเคชันมือถือผ่านฟังก์ชันนี้ เพื่อการเข้าถึงผู้ใช้ที่ดียิ่งขึ้น เราแนะนำให้คุณโปรโมตแอปพลิเคชันมือถือของเว็บไซต์อย่างต่อเนื่อง</li><li>การใช้งานฟังก์ชันนี้จำเป็นต้องเปิดใช้งานปลั๊กอินมือถือเสียก่อน</li><li><strong>โปรดติดตามการอัปเดตของ "<a href="https://addon.dismall.com/?@mobile.plugin">แอปพลิเคชันมือถือ</a>" ในศูนย์รวมแอป รายละเอียดการใช้งานจะระบุไว้ในปลั๊กอิน</strong></li>',
	'members_newsletter_sms_tips' => '<li>คุณสามารถส่งการแจ้งเตือนผ่าน SMS ไปยังเบอร์มือถือที่สมาชิกผูกไว้ผ่านฟังก์ชันนี้ เพื่อการเข้าถึงผู้ใช้ที่ดียิ่งขึ้น แนะนำให้ผู้ใช้ผูกเบอร์มือถือให้เรียบร้อย</li><li>การใช้งานฟังก์ชันนี้จำเป็นต้องมีการผูกบริการ SMS Gateway</li><li><strong>โปรดระมัดระวังเรื่องจำนวนและตัวอักษรของ SMS ที่ส่ง เนื่องจากส่วนนี้ไม่ได้ถูกควบคุมโดยระบบความปลอดภัย SMS ของ Discuz! X ปริมาณข้อมูลที่มากเกินไปอาจทำให้เกิดค่าใช้จ่ายสูง</strong></li>',

