	'founder_patchstatus_error4' => 'ไม่สามารถใช้วิธี FTP ได้ โปรดตรวจสอบว่าข้อมูลบัญชี FTP ถูกต้องหรือไม่',
	'founder_patchstatus_error5' => 'เกิดปัญหาในการคัดลอกไฟล์ โปรดตรวจสอบว่าไดเรกทอรีไฟล์ซอร์สโค้ดและไดเรกทอรีย่อยสามารถอ่านและเขียนได้ หรือไฟล์อาจถูกล็อกอยู่ โปรดปิดเว็บไซต์แล้วดำเนินการใหม่อีกครั้ง',
	'founder_patchstatus_error6' => 'เกิดปัญหาในการแก้ไขช่องโหว่และเกิดปัญหาขณะย้อนกลับ โปรดกู้คืนไฟล์โดยเร็วที่สุด สามารถหาไฟล์สำรองได้ในไดเรกทอรีระดับเดียวกัน',
	'founder_patch_tips' => '<li>คำอธิบายสถานะการแก้ไขช่องโหว่:</li>
							<li>
								<em class="fixed">&nbsp;2</em> ไฟล์อาจถูกแก้ไขไปแล้ว ไม่พบช่องโหว่<br />
								<em class="fixed">&nbsp;1</em> แก้ไขเสร็จสิ้น<br />
								<em class="unfixed">&nbsp;0</em> ยังไม่ได้แก้ไข<br />
								<em class="unfixed">-1</em> รหัสช่องโหว่ว่างเปล่า ข้อมูลช่องโหว่ในเครื่องของคุณอาจมีปัญหา<br />
								<em class="unfixed">-2</em> ไม่พบไฟล์ซ่อมแซมช่องโหว่หรือไฟล์ไม่สามารถแก้ไขได้ โปรดตรวจสอบและเปลี่ยนสิทธิ์เป็นอ่านและเขียนได้ (777)<br />
								<em class="unfixed">-3</em> การเขียนไฟล์ชั่วคราวผิดพลาด โปรดตรวจสอบว่าไดเรกทอรี data สามารถเขียนข้อมูลได้หรือไม่<br />
								<em class="unfixed">-4</em> ไม่สามารถใช้วิธี FTP ได้ โปรดตรวจสอบว่าข้อมูลบัญชี FTP ถูกต้องหรือไม่<br />
								<em class="unfixed">-5</em> เกิดปัญหาในการคัดลอกไฟล์ โปรดตรวจสอบว่าไดเรกทอรีไฟล์ซอร์สโค้ดและไดเรกทอรีย่อยสามารถอ่านและเขียนได้ หรือไฟล์อาจถูกล็อกอยู่ โปรดปิดเว็บไซต์แล้วดำเนินการใหม่อีกครั้ง<br />
								<em class="unfixed">-6</em> เกิดปัญหาในการแก้ไขช่องโหว่และเกิดปัญหาขณะย้อนกลับ โปรดกู้คืนไฟล์โดยเร็วที่สุด สามารถหาไฟล์สำรองได้ในไดเรกทอรีระดับเดียวกัน
							</li>',

