	'usergroups_tips' => '<li>กลุ่มผู้ใช้งานแบ่งเป็น กลุ่มระบบ, กลุ่มสมาชิก และกลุ่มกำหนดเอง โดยกลุ่มกำหนดเองสามารถตั้งเป็นกลุ่มเลื่อนระดับได้ กลุ่มสมาชิกและกลุ่มเลื่อนระดับจะถูกกำหนดตามคะแนนเครดิตและสิทธิ์ ส่วนกลุ่มอื่น ๆ จะถูกกำหนดโดยผู้ดูแลและจะไม่เปลี่ยนแปลงโดยระบบอัตโนมัติ</li><li>กลุ่มระบบและกลุ่มที่ไม่ใช่กลุ่มเลื่อนระดับไม่จำเป็นต้องระบุคะแนนเครดิต Discuz! ได้เตรียมชื่อตำแหน่งระบบไว้ 8 ตำแหน่งตั้งแต่ผู้ดูแลระบบจนถึงผู้เยี่ยมชม กลุ่มที่ไม่เปิดเป็นสาธารณะจะไม่สามารถเข้าร่วมเองได้ ต้องให้ผู้ดูแลเพิ่มให้เท่านั้น</li><li>กลุ่มผู้ใช้งานสมาชิกต้องมีอย่างน้อยสองกลุ่ม โดยเกณฑ์คะแนนต่ำสุดต้องเป็นค่าติดลบ (ค่าใดก็ได้) และ 0 มิฉะนั้นอาจเกิดปัญหาผู้ใช้ไม่ตรงกับกลุ่มใดเลย</li><li>กลุ่มผู้ใช้งานเลื่อนระดับต้องมีอย่างน้อยสองกลุ่ม โดยเกณฑ์คะแนนต่ำสุดต้องเป็น 0 มิฉะนั้นอาจเกิดปัญหาผู้ใช้ไม่ตรงกับกลุ่มใดเลย</li>',
