	'usergroups_edit_system' => 'รูปแบบกลุ่มผู้ใช้งาน',
	'usergroups_edit_system_tips' => '<li><b><u>กลุ่มผู้ใช้งานแบบเลื่อนระดับ</u></b><br />เมื่อตั้งค่าเป็น “กลุ่มผู้ใช้งานแบบเลื่อนระดับ” คุณสามารถกำหนดกลุ่มเริ่มต้นและกลุ่มย่อยที่สังกัดได้ จากนั้นจึงกำหนดช่วงคะแนนเครดิตในหน้ารายการกลุ่มผู้ใช้งาน</li><li><b><u>กลุ่มผู้ใช้งานแบบไม่สาธารณะ</u></b><br />เมื่อตั้งค่าเป็น “กลุ่มผู้ใช้งานแบบไม่สาธารณะ” ไม่ว่าจะใช้เป็นกลุ่มหลักหรือกลุ่มเพิ่มเติม ผู้ดูแลระบบจะต้องเป็นผู้เพิ่มสมาชิกเข้ากลุ่มนี้ด้วยตนเองเท่านั้น</li><li><b><u>กลุ่มผู้ใช้งานแบบสาธารณะ</u></b><br />เมื่อตั้งค่าเป็น “กลุ่มผู้ใช้งานแบบสาธารณะ” และกลุ่มปัจจุบันของผู้ใช้ได้รับอนุญาตให้เข้า/ออกจากกลุ่มสาธารณะได้ ผู้ใช้จะสามารถเลือกกลุ่มนี้เป็นกลุ่มหลักหรือกลุ่มเพิ่มเติมได้ในหน้าสมาชิก เมื่อตั้งเป็นกลุ่มหลัก สิทธิ์การใช้งานจะเป็นไปตามกลุ่มนี้ เมื่อตั้งเป็นกลุ่มเพิ่มเติม จะช่วยให้สามารถเข้าถึงบอร์ดเฉพาะที่อนุญาตให้กลุ่มนี้เข้าถึงได้เท่านั้น</li><li><b>กลุ่มสาธารณะแบบเก็บค่าธรรมเนียม</b>: <br />คุณสามารถกำหนดให้ผู้ใช้ต้องจ่ายเครดิตธุรกรรมเพื่อเข้ากลุ่ม โดยระยะเวลาที่ได้รับสิทธิ์จะขึ้นอยู่กับจำนวนเครดิตที่จ่าย คุณสามารถกำหนดราคาต่อวันได้ เมื่อครบกำหนดระบบจะนำสิทธิ์ของกลุ่มนี้ออกจากผู้ใช้โดยอัตโนมัติ</li><li><b>กลุ่มสาธารณะแบบฟรี</b>: <br />ผู้ใช้สามารถเลือกเข้าร่วมกลุ่มนี้ได้เองในหน้าสมาชิกเพื่อรับสิทธิ์และชื่อตำแหน่งของกลุ่มโดยไม่ต้องเสียค่าใช้จ่ายใด ๆ</li>',
	'usergroups_edit_system_public' => 'กลุ่มผู้ใช้งานสาธารณะ',
	'usergroups_edit_system_buy' => 'กลุ่มผู้ใช้งานแบบเก็บค่าธรรมเนียม',
	'usergroups_edit_system_free' => 'กลุ่มผู้ใช้งานแบบฟรี',
	'usergroups_edit_system_public_comment' => 'กำหนดว่าเป็นกลุ่มผู้ใช้งานสาธารณะหรือไม่ หมายเหตุ: โปรดตรวจสอบความจำเป็นก่อนเปิดใช้งาน เพราะหากผู้ใช้เข้าร่วมกลุ่มไปแล้ว แม้จะเปลี่ยนเป็นแบบไม่สาธารณะในภายหลัง ระบบก็ไม่สามารถนำผู้ใช้ออกจากกลุ่มแบบกลุ่มได้นอกจากจะลบกลุ่มทิ้ง ทั้งนี้กลุ่มสาธารณะไม่สามารถผูกกับกลุ่มผู้ดูแลระบบได้เพื่อความปลอดภัย',
	'usergroups_edit_system_dailyprice' => 'ราคาต่อวันสำหรับกลุ่มสาธารณะแบบเก็บค่าธรรมเนียม',
	'usergroups_edit_system_dailyprice_comment' => 'หากต้องการให้ผู้ใช้จ่ายเครดิตธุรกรรมเพื่อเข้าร่วมกลุ่ม โปรดระบุราคาต่อวัน (หน่วยตามเครดิตธุรกรรมที่ใช้) เช่น ตั้งไว้ 2 หากผู้ใช้ซื้อสิทธิ์ 30 วัน ต้องจ่าย 2*30=60 เครดิต และจะพ้นสภาพกลุ่มเมื่อครบกำหนด หากตั้งเป็น 0 จะถือว่าเป็นกลุ่มสาธารณะแบบฟรี ฟังก์ชันนี้จะมีผลต่อเมื่อตั้งเป็นกลุ่มสาธารณะและเปิดใช้งานเครดิตธุรกรรมแล้วเท่านั้น',
	'usergroups_edit_system_minspan' => 'ระยะเวลาซื้อขั้นต่ำสำหรับกลุ่มสาธารณะแบบเก็บค่าธรรมเนียม (วัน)',
	'usergroups_edit_system_minspan_comment' => 'กำหนดระยะเวลาขั้นต่ำในการจ่ายเครดิตเพื่อเข้าร่วมกลุ่ม โปรดระบุค่าตั้งแต่ 1 ขึ้นไป เช่น ราคาต่อวันคือ 2 และซื้อขั้นต่ำคือ 10 วัน ผู้ใช้ต้องจ่ายอย่างน้อย 20 เครดิตเพื่อเข้ากลุ่มเป็นเวลา 10 วัน ฟังก์ชันนี้มีผลเฉพาะกลุ่มแบบเก็บค่าธรรมเนียมเท่านั้น',
	'usergroups_edit_system_guest_portal_tips' => '<li>สำหรับการตั้งค่ากลุ่มผู้เยี่ยมชม สิทธิ์การเผยแพร่ที่เกี่ยวข้องกับพอร์ทัลจะไม่มีผล</li>',
	'usergroups_edit_system_guest_home_tips' => '<li>สำหรับการตั้งค่ากลุ่มผู้เยี่ยมชม สิทธิ์การเผยแพร่และความคิดเห็นที่เกี่ยวข้องกับสเปซจะไม่มีผล</li>',

