	'threads_postposition' => 'เพิ่มประสิทธิภาพโพสต์',
	'threads_postposition_tips' => '<li>ฟังก์ชันนี้ใช้สำหรับปรับปรุงประสิทธิภาพการแสดงผลของกระทู้ที่มีจำนวนการตอบกลับสูงมาก โดยปกติเมื่อการตอบกลับเกิน 5,000 รายการ หรือคาดว่าจะถึงจำนวนดังกล่าว คุณสามารถนำกระทู้เข้าสู่คิวการเพิ่มประสิทธิภาพได้</li>
					<li>เมื่อกระทู้อยู่ในคิวการเพิ่มประสิทธิภาพแล้ว ไม่แนะนำให้ลบโพสต์ใด ๆ ในกระทู้นั้น หากเนื้อหาทำผิดกฎ แนะนำให้ใช้วิธีแบนโพสต์แทน</li>
					<li>เมื่อมีการจัดกิจกรรมแข่งตอบ ระบบจะนำกระทู้นั้นเข้าสู่คิวการเพิ่มประสิทธิภาพโดยอัตโนมัติ นอกจากนี้คุณยังสามารถเพิ่มกระทู้ที่มีการตอบกลับจำนวนมากเข้าสู่คิวได้ด้วยตนเองที่นี่</li>
				',

