	'prune_tips' => '<li>การลบโพสต์แบบกลุ่มใช้สำหรับลบโพสต์ที่ทำผิดกฎเท่านั้น หากคุณต้องการลบกระทู้เก่าจำนวนมาก โปรดใช้ฟังก์ชันจัดการกระทู้แบบกลุ่มแทน</li><li>การใช้งานฟังก์ชันนี้ จำเป็นต้องระบุเงื่อนไขอย่างน้อย 2 อย่างประกอบกัน ได้แก่ ช่วงเวลาเริ่มต้นหรือสิ้นสุด อย่างใดอย่างหนึ่ง ร่วมกับ ชื่อผู้ใช้, ไอพี หรือคำสำคัญในเนื้อหา อย่างใดอย่างหนึ่ง มิฉะนั้นจะไม่สามารถดำเนินการได้</li><li>หากโพสต์ที่ตรงตามเงื่อนไขเป็นโพสต์แรกของกระทู้ หรือกระทู้นั้นไม่มีการตอบกลับอื่น ระบบจะลบกระทู้นั้นออกทั้งกระทู้</li><li>หากคุณไม่ใช่ผู้ดูแลระบบ คุณจะสามารถลบได้เฉพาะโพสต์ในช่วงเวลาที่กำหนดจนถึงปัจจุบันเท่านั้น</li><li>ผู้ช่วยผู้ดูแลระบบสามารถลบโพสต์ย้อนหลังได้ 2 สัปดาห์ (14 วัน) ส่วนผู้ดูแลบอร์ดลบย้อนหลังได้ 1 สัปดาห์ (7 วัน) และลบได้เฉพาะในบอร์ดที่ตนเองดูแลเท่านั้น</li><li>คำสำคัญสามารถใช้ตัวกำหนดขอบเขต {x} เพื่อระบุจำนวนตัวอักษรที่ละเว้นได้ระหว่างสองตัวอักษร โดย x คือจำนวนตัวอักษร เช่น "a{1}s{2}s" (ไม่ต้องใส่เครื่องหมายอัญประกาศ) จะสามารถค้นหาได้ทั้ง "<b>ass</b>", "<b>a</b>x<b>s</b>x<b>s</b>" และ "<b>a</b>x<b>s</b>xx<b>s</b>" เป็นต้น</li>',
