	'misc_cron' => 'งานตั้งเวลา',
	'misc_cron_list' => 'รายการงานตั้งเวลา',
	'misc_cron_tips' => '<li>งานตั้งเวลา (Cron) คือฟังก์ชันที่ Discuz! เตรียมไว้เพื่อให้ระบบรันงานเฉพาะทางโดยอัตโนมัติตามเวลาที่กำหนด คุณสามารถใช้ฟังก์ชันนี้ในการขยายความสามารถของเว็บไซต์ได้</li><li>งานตั้งเวลาเป็นส่วนที่มีความเกี่ยวข้องอย่างใกล้ชิดกับแกนหลักของระบบ การตั้งค่าที่ไม่ถูกต้องอาจส่งผลกระทบต่อการทำงานของเว็บไซต์อย่างรุนแรง โปรดเพิ่มหรือแก้ไขรายการงานเมื่อคุณมีความเข้าใจในคุณลักษณะของมันอย่างถ่องแท้และทราบถึงผลลัพธ์ที่จะตามมาเท่านั้น</li><li>ฟังก์ชันนี้จะอ้างอิงเวลาตามส่วนต่างเวลาเริ่มต้นของระบบเสมอ โดยจะไม่เปลี่ยนแปลงตามการตั้งค่าเวลาส่วนตัวของผู้ใช้หรือผู้ดูแลระบบ</li><li>ตามปกติงานตั้งเวลาจะถูกกระตุ้นโดยการเข้าใช้งานของผู้ใช้ หากคุณต้องการเปลี่ยนไปใช้การกระตุ้นจากระบบโดยตรง โปรดศึกษาคำแนะนำในไฟล์ /api/remote/cron.php</li>',
