	'misc_cron_edit_tips' => '<li>คุณกำลังแก้ไขงานตั้งเวลาที่เป็นค่าเริ่มต้นของระบบ หากไม่มีความเข้าใจโครงสร้างของ Discuz! อย่างถ่องแท้ แนะนำให้หลีกเลี่ยงการแก้ไขการตั้งค่าเดิม</li><li>โปรดบันทึกการตั้งค่าเดิมไว้ก่อนการแก้ไข เนื่องจากการตั้งค่าที่ไม่ถูกต้องอาจทำให้เว็บไซต์เกิดข้อผิดพลาดที่คาดไม่ถึงได้</li>',
