	'misc_censor' => 'กรองคำไม่สุภาพ',
	'misc_censor_tips' => '<li>เนื้อหาก่อนการแทนที่สามารถใช้ตัวกำหนดขอบเขต {x} เพื่อระบุจำนวนไบต์ที่สามารถละเว้นได้ระหว่างตัวอักษร เช่น "a{1}s{2}s" (ไม่ต้องใส่เครื่องหมายอัญประกาศ) จะสามารถกรองได้ทั้ง "<b>ass</b>", "<b>a</b>x<b>s</b>x<b>s</b>" และ "<b>a</b>x<b>s</b>xx<b>s</b>" เป็นต้น สำหรับอักขระจีนในรุ่น UTF-8 หนึ่งตัวอักษรจะเท่ากับ 3 ไบต์</li><li>เพื่อไม่ให้กระทบต่อประสิทธิภาพของระบบ โปรดอย่าตั้งค่าคำกรองที่ไม่มีความจำเป็นมากเกินไป</li><li>การคัดกรองจะมีผลเฉพาะกับเนื้อหาในเว็บบอร์ดเท่านั้น</li><li>หากคุณไม่ใช่ผู้ดูแลระบบ คุณจะแก้ไขหรือลบได้เฉพาะรายการที่คุณเพิ่มเข้าไปเองเท่านั้น</li><li>หากคำที่ละเอียดอ่อนขึ้นต้นและลงท้ายด้วย "/" จะถือว่าเป็นรูปแบบ Regular Expression (Regex) ซึ่งสามารถใช้ "(n)" ในช่องแทนที่เพื่ออ้างอิงกลุ่มย่อยใน Regex ได้ เช่น "/1\d{10}([^\d]+|$)/" แทนที่ด้วย "เบอร์มือถือ(1)"</li>',
