	'misc_censor_batch_add' => 'เพิ่มแบบกลุ่ม',
	'misc_censor_batch_add_tips' => '<li>กรอกคำกรองหนึ่งชุดต่อบรรทัด โดยคั่นระหว่างคำละเอียดอ่อนและคำที่ใช้แทนที่ด้วยเครื่องหมาย “=”</li><li>หากต้องการห้ามโพสต์ข้อความที่มีคำนั้น ๆ แทนที่จะเป็นการกรองแทนที่ ให้ตั้งค่าคำแทนที่เป็น {BANNED} หากต้องการให้โพสต์นั้นต้องรอการตรวจสอบจากทีมงานก่อนแสดงผล ให้ตั้งค่าเป็น {MOD} (มีผลเฉพาะในเว็บบอร์ด)</li><li>หากต้องการเปลี่ยนคำนั้นเป็น ** โดยตรง ให้กรอกเพียงคำละเอียดอ่อนอย่างเดียว</li><li>ตัวอย่าง:<br />คำไม่ดี1<br />คำไม่ดี2<br />คำแย่=คำดี<br />คำต้องห้าม={BANNED}</li><li>รองรับการนำเข้า/ส่งออกพร้อมหมวดหมู่ หากไฟล์ที่นำเข้าไม่มีหมวดหมู่ คุณสามารถเลือกหมวดหมู่ปลายทางได้เอง หากไม่เลือกจะถูกจัดเข้าหมวดหมู่เริ่มต้น</li>',
