	'smilies_edit_add_tips' => 'ไม่พบรูปภาพอีโมจิใหม่ในไดเรกทอรี {smurl} ชื่อไฟล์รูปภาพต้องประกอบด้วยตัวเลข, อักษรภาษาอังกฤษ 26 ตัว, ขีดล่าง, เว้นวรรค หรือสัญลักษณ์ <>-.&[]() และความยาวต้องไม่เกิน 30 ไบต์ มิฉะนั้นระบบจะไม่รองรับ โปรดอัปโหลดรูปภาพผ่าน FTP ไปยังไดเรกทอรี {smurl} แล้วคลิก “ค้นหาอีกครั้ง”',
