	'smilies_import' => 'นำเข้าอีโมจิ',
	'smilies_tips' => '<li>หากต้องการเพิ่มอีโมจิ โปรดอัปโหลดรูปภาพไปยังไดเรกทอรีที่เกี่ยวข้อง (static/image/smiley/ชื่อหมวดหมู่/)</li><li>รองรับไฟล์รูปภาพรูปแบบ "JPG, GIF, PNG" ชื่อไฟล์ต้องประกอบด้วยตัวเลข, อักษรภาษาอังกฤษ, ขีดล่าง, เว้นวรรค หรือสัญลักษณ์ <>-.&[]() และยาวไม่เกิน 30 ไบต์</li><li>โปรดอย่าใส่จำนวนอีโมจิมากเกินไปเพื่อประหยัดทรัพยากรเซิร์ฟเวอร์</li>',
	'smilies_tips_smileytypes' => '<li>การส่งออกอีโมจิจะรวมข้อมูลหมวดหมู่และรหัสอีโมจิ สำหรับไฟล์รูปภาพโปรดดาวน์โหลดผ่าน FTP</li><li>โปรดอย่าเปิดใช้งานหมวดหมู่อีโมจิมากเกินไปในเวลาเดียวกัน และควรควบคุมความยาวของชื่อหมวดหมู่เพื่อให้อยู่ในขอบเขตที่หน้าต่างอีโมจิจะแสดงผลได้ครบถ้วน</li><li>คุณสามารถตั้งค่าหมวดหมู่อีโมจิเริ่มต้นได้ในส่วนสไตล์หน้าตาเว็บ หากต้องการลบหมวดหมู่ ต้องลบอีโมจิทั้งหมดในหมวดหมู่นั้นออกก่อน</li>',
	'smiliesupload_tips' => 'ไม่พบหมวดหมู่อีโมจิที่ยังไม่ได้ใช้งาน คุณสามารถสร้างโฟลเดอร์หมวดหมู่ใหม่ภายใต้ static/image/smiley/ ผ่าน FTP และอัปโหลดรูปภาพลงไป จากนั้นจึงรีเฟรชหน้านี้ ชื่อโฟลเดอร์ต้องประกอบด้วยตัวเลข, อักษรภาษาอังกฤษ และขีดล่างเท่านั้น',
	'smilies_emoij_tips' => 'โปรดระบุ Emoji ที่ต้องการเพิ่ม',

