	'click_edit_tips' => '<li>ฟังก์ชันนี้ใช้สำหรับตั้งค่าไอคอนแสดงความรู้สึกต่อ ไดอารี่/รูปภาพ/บทความ โปรดระบุชื่อไฟล์รูปภาพและอัปโหลดไปยัง static/image/click/ หรือระบุ URL ของรูปภาพโดยตรง</li><li><strong>คำเตือน: หากเปลี่ยนลำดับของไอคอนหลังจากเว็บไซต์เปิดให้บริการไประยะหนึ่งแล้ว จะส่งผลต่อผลลัพธ์ของความรู้สึกเดิมที่สมาชิกเคยแสดงไว้</strong></li><li>เปิดใช้งานได้สูงสุด 8 รายการต่อหนึ่งประเภท</li>',
