	'misc_stamp_listtips' => '<li>ตราประทับจะแสดงในหน้าเนื้อหากระทู้ ส่วนไอคอนการรับรองจะแสดงในหน้ารายการกระทู้</li><li>ระบบสำรองตำแหน่งรูปภาพไว้ 100 ตำแหน่ง คือไอดี 0 ถึง 99</li><li>โปรดอย่าเปลี่ยนไอดีรูปภาพโดยพลการ เพราะจะทำให้ตราประทับและไอคอนที่เคยใช้งานไปแล้วแสดงผลผิดพลาด</li><li>เมื่อตั้งค่าการดำเนินการที่เกี่ยวข้อง ตราประทับจะถูกเพิ่มลงในกระทู้อัตโนมัติเมื่อมีการดำเนินการนั้น ๆ หากตั้งค่าไอคอนที่เกี่ยวข้องไว้ ไอคอนจะถูกเพิ่มในรายการกระทู้อัตโนมัติพร้อมกับตราประทับ ทั้งนี้ไม่สามารถตั้งค่าการดำเนินการและไอคอนพร้อมกันได้</li>',
