	'editorblock_usage' => 'บทช่วยสอนการใช้งาน',
	'editorblock_usage_content' => '<ul><li>วิธีการใช้ตัวแปร: “<span style="color: green;">{ชื่อฟิลด์}</span>” สำหรับข้อมูลหลายระดับให้ใช้ “.” ในการเชื่อมต่อ เช่น “<span style="color: green;">{ฟิลด์1.ฟิลด์2.ฟิลด์3}</span>”</li><li>ตัวอย่างการใช้ตัวแปร: {id}, {type}, {data.alignment}, {data.items.text}</li><li>รองรับการวนลูปด้วย “[loop]” ตัวอย่างรหัสข้อมูลบล็อก เช่น: <pre>{
    "data": {
        ...
        "items": [
        	{
        		"text" : "abc"
        	},
        	{
        		"text" : "def"
        	},
        	...
        ]
    }
}</pre>
รูปแบบการวนลูป: <pre>
&lt;ul&gt;
[loop data.items]
   &lt;li&gt;{text}&lt;/li&gt;
[/loop]
&lt;/ul&gt;
</pre>
<br/>
ดัชนีการวนลูป (ใส่ไว้ในเนื้อหาลูปเพื่อใช้นับจำนวนอัตโนมัติ): <pre>
[loopindex]
</pre>
<br/>
การแสดงผลหลายคอลัมน์ (ใส่ไว้ในเนื้อหาลูปเพื่อระบุบล็อกข้อมูลย่อย ใช้สำหรับการแสดงผลหลายคอลัมน์เท่านั้น): <pre>
[column blocks]
</pre>
<br/>
รูปแบบการใช้เงื่อนไข IF: <pre>
[if data.items=1]
   ตัวแปร {text} หรือข้อความทั่วไป
[/if]
</pre>
<br/>
การแปลง URL เป็นที่อยู่แบบเต็ม: <pre>
[url data.file.url]
</pre>
<br/>
การดึงรหัส AID ของไฟล์แนบที่เข้ารหัส: <pre>
[attach data.file.aid]
</pre>
</li><li>รหัสสไตล์ CSS จะต้องเขียนอยู่ภายในเครื่องหมาย &lt;style type="text/css"&gt;......&lt;/style&gt; อย่างเคร่งครัด</li></ul>',

	'editorblock_usage_css_content' => '<ul><li>สไตล์ CSS ส่วนกลางจะถูกโหลดในหน้าเนื้อหาที่เผยแพร่ด้วย JSON Editor</li><li>รหัสสไตล์ CSS จะต้องเขียนอยู่ภายในเครื่องหมาย &lt;style type="text/css"&gt;......&lt;/style&gt; อย่างเคร่งครัด</li></ul>',

