	'tasks_tips' => '<li>เฉพาะภารกิจที่มีสถานะ “ใช้งานได้” เท่านั้นที่สมาชิกจะมองเห็นและลงทะเบียนเข้าร่วมได้</li>',
	'tasks_tips_edit' => '<li>ภารกิจต้องอยู่ในสถานะ “ใช้งานได้” สมาชิกจึงจะสามารถมองเห็นและเข้าร่วมได้</li><li>คุณสามารถกำหนดเวลาเริ่มต้นของภารกิจได้ หากไม่ระบุ ภารกิจจะถือว่าเริ่มต้นทันทีที่บันทึก</li>',
	'tasks_tips_add_member' => '<li>ภารกิจประเภทสมาชิกปัจจุบันมี 3 แบบ: เพิ่มเพื่อน, เก็บกระทู้เป็นรายการโปรด และการใช้ไอเท็มเวทย์ เพื่อกระตุ้นให้สมาชิกใช้งานฟังก์ชันต่าง ๆ ของเว็บบอร์ด</li><li>การตั้งค่าเงื่อนไขที่หลากหลายจะช่วยสร้างภารกิจที่น่าสนใจสำหรับเว็บไซต์ของคุณ</li>',
	'tasks_tips_add_post' => '<li>ภารกิจประเภทโพสต์ปัจจุบันมี 3 แบบ: ตั้งกระทู้ใหม่, ตอบกระทู้ และตั้งกระทู้หรือตอบกระทู้</li><li>หากระบุบอร์ดสำหรับภารกิจ โปรดตรวจสอบสิทธิ์ของกลุ่มผู้ใช้งานและบอร์ดนั้น ๆ ด้วย มิฉะนั้นสมาชิกอาจจะไม่สามารถทำภารกิจให้สำเร็จได้หากไม่มีสิทธิ์โพสต์ในบอร์ดที่กำหนด</li><li>สำหรับภารกิจตอบกระทู้ คุณสามารถระบุกระทู้หรือชื่อผู้เขียนที่ต้องไปตอบได้ แต่โปรดตรวจสอบว่ากระทู้นั้นยังมีอยู่จริง</li>',
	'tasks_tips_add_type' => '<li>ภารกิจระบบอยู่ที่ source/class/task/ ส่วนภารกิจปลั๊กอินอยู่ที่ source/plugin/ชื่อปลั๊กอิน/task/</li><li>นักพัฒนาโปรดอ่าน “<a href="https://open.dismall.com/?!devdoc" target="_blank">เอกสารทางเทคนิค Discuz!</a>” ก่อนออกแบบประเภทภารกิจใหม่</li>',
