	'ec_alipay' => 'ตั้งค่า Alipay',
	'ec_alipay_on' => 'เปิดใช้งาน Alipay หรือไม่',
	'ec_alipay_tips' => '<li>“Alipay” (<a href="http://www.alipay.com" target="_blank">http://www.alipay.com</a>) เป็นแพลตฟอร์มการชำระเงินออนไลน์ชั้นนำของจีน สร้างโดยบริษัท Alibaba เพื่อให้บริการแก่ผู้ใช้ Discuz! ในการซื้อเครดิตและเป็นแพลตฟอร์มซื้อขายแบบ B2C และ C2C เพียงตั้งค่าสั้น ๆ คุณก็สามารถเปลี่ยนเนื้อหาและความนิยมของเว็บบอร์ดให้กลายเป็นแหล่งรายได้สำคัญนอกเหนือจากโฆษณาได้</li><li><b>เนื่องจากเกี่ยวข้องกับการทำธุรกรรมด้วยเงินจริง เพื่อหลีกเลี่ยงความสูญเสียจากการตั้งค่าที่ผิดพลาด ก่อนเริ่มใช้งานฟังก์ชันซื้อขายเครดิตผ่าน Alipay โปรดอ่านส่วนพาณิชย์อิเล็กทรอนิกส์ใน “คู่มือการใช้งาน” อย่างละเอียด และเริ่มตั้งค่าเมื่อคุณเข้าใจขั้นตอนและวิธีการใช้งานอย่างครบถ้วนแล้วเท่านั้น</b></li><li>การใช้บริการ Alipay เป็นไปตามความสมัครใจของผู้ใช้เอง ทาง Tencent Cloud จะไม่รับผิดชอบต่อความสูญเสียใด ๆ ที่เกิดจากการใช้งานฟังก์ชันนี้ ยกเว้นกรณีที่เกิดจากความประมาทเลินเล่อโดยเจตนาของ Discuz! เท่านั้น</li><li>สายด่วนบริการลูกค้า Alipay คือ 95188</li>',
	'ec_alipay_account' => 'บัญชี Alipay สำหรับรับเงิน',
	'ec_alipay_account_comment' => 'หากเปิดใช้งานฟังก์ชันแลกเปลี่ยนหรือซื้อขาย โปรดกรอกบัญชี Alipay ที่ใช้งานจริง เพื่อใช้รับเงินจากการที่สมาชิกแลกเปลี่ยนเครดิตด้วยเงินสด หากบัญชีไม่ถูกต้องหรือคีย์ความปลอดภัยผิดพลาด จะส่งผลให้ระบบไม่สามารถเติมเครดิตให้ผู้ใช้โดยอัตโนมัติหลังจากชำระเงินได้<br />หากคุณยังไม่มีบัญชี Alipay <a href="http://www.alipay.com/redir.do?id=307&site=allbbs&target=https%3A%2F%2Fwww.alipay.com%2Fuser%2Fuser_register.htm" target="_blank">คลิกที่นี่เพื่อลงทะเบียน</a>',
	'ec_alipay_check_comment' => 'การทดสอบนี้จะจำลองการสร้างรายการสั่งซื้อจำนวน 0.01 หยวน หากส่งข้อมูลแล้วปรากฏหน้าจอการชำระเงิน แสดงว่าฟังก์ชัน Alipay ของเว็บไซต์ทำงานปกติ',
	'ec_alipay_check_virtualgoodssubject' => 'ทดสอบสินค้าเสมือน',
