	'ec_alipay_contract_comment' => 'หากบัญชี Alipay ของคุณเป็นบัญชีผู้ค้าที่ลงทะเบียนสัญญาไว้ คุณสามารถเลือก “ใช่” เพื่อใช้แพลตฟอร์มบริการผู้ค้าของคุณเองได้ หากยังไม่ได้ลงทะเบียน <a href="http://act.life.alipay.com/systembiz/discuz/" target="_blank">คลิกที่นี่เพื่อลงทะเบียนสัญญา</a>',
	'ec_alipay_securitycode' => 'คีย์ตรวจสอบความปลอดภัยการทำธุรกรรม (Key)',
	'ec_alipay_securitycode_comment' => 'สำหรับผู้ค้าที่ลงทะเบียน สามารถกรอกคีย์ตรวจสอบความปลอดภัยที่ Alipay ออกให้ได้ที่นี่ โดยตรวจสอบได้จากเมนูบริการผู้ค้าในเว็บไซต์ทางการของ Alipay',
	'ec_alipay_partner' => 'รหัสพันธมิตร (PID)',
	'ec_alipay_partner_comment' => 'กรอกหมายเลข PID ที่ได้รับจาก Alipay โดยค่าธรรมเนียมจะเป็นไปตามข้อตกลงที่คุณทำไว้กับ Alipay<br/>หากยังไม่มี PID/Key <a href="https://b.alipay.com/order/pidKey.htm?pid=2088501719138773&product=fastpay" id="aliapitype" target="_blank">คลิกที่นี่เพื่อตรวจสอบ</a> หรือติดต่อ 0571-88158090 หากพบปัญหาเทมเพลตสัญญาซ้ำซ้อน',
	'ec_alipay_creditdirectpay' => 'ใช้อินเทอร์เฟซการรับชำระเงินทันที',
	'ec_alipay_creditdirectpay_comment' => 'หากสัญญาของคุณรองรับ Direct Pay (ไม่ใช่ Dual Interface มาตรฐาน) สามารถเลือกหัวข้อนี้เพื่อให้การเติมเครดิตรองรับเฉพาะการชำระเงินแบบได้รับเงินทันทีเท่านั้น',
	'ec_alipay_sign_mode' => 'รูปแบบการลงลายชื่อดิจิทัล',
	'ec_alipay_sign_mode_01' => 'โหมด Public Key ปกติ',
	'ec_alipay_sign_mode_02' => 'โหมดใบรับรอง (Public Key Certificate)',
	'ec_alipay_sign_mode_comment' => 'Alipay Open Platform: <a href="https://open.alipay.com/" target="_blank">ดูข้อมูล</a>; สำหรับนิติบุคคลที่เกี่ยวข้องกับ <a href="https://opendocs.alipay.com/open/291/hfaalq" target="_blank">อินเทอร์เฟซด้านเงินทุน</a> จำเป็นต้องใช้ <b>โหมดใบรับรอง</b>; สำหรับบุคคลธรรมดาแนะนำให้ใช้ <b>โหมด Public Key ปกติ</b>; รายละเอียดการตั้งค่า: <a href="https://opendocs.alipay.com/mini/introduce/01p6u8" target="_blank">การกำหนดค่าการลงลายชื่ออินเทอร์เฟซ</a>',
	'ec_alipay_appid' => '(จำเป็น) AppID',
	'ec_alipay_appid_comment' => 'หมายเลข AppID ที่ Alipay ออกให้แก่นักพัฒนา <a href="https://open.alipay.com/platform/developerIndex.htm" target="_blank">ดูรายการแอปของฉัน</a>',
	'ec_alipay_app_private_key' => '(จำเป็น) RSA2(SHA256) Private Key ของนักพัฒนา',
	'ec_alipay_app_private_key_comment' => 'ดูวิธีรับได้ที่ <a href="https://opendocs.alipay.com/open/291/105971#%E6%99%AE%E9%80%9A%E5%85%AC%E9%92%A5%E6%96%B9%E5%BC%8F" target="_blank">การรับ Public Key ปกติ</a>',
	'ec_alipay_app_private_key_b_comment' => 'ดูวิธีรับได้ที่ <a href="https://opendocs.alipay.com/open/291/105971#%E5%85%AC%E9%92%A5%E8%AF%81%E4%B9%A6%E6%96%B9%E5%BC%8F" target="_blank">การรับใบรับรอง Public Key</a>',
	'ec_alipay_public_key' => '(จำเป็น) RSA2(SHA256) Alipay Public Key',
	'ec_alipay_public_key_comment' => 'ดูวิธีรับได้ที่ <a href="https://opendocs.alipay.com/open/291/105971#%E6%99%AE%E9%80%9A%E5%85%AC%E9%92%A5%E6%96%B9%E5%BC%8F" target="_blank">การรับ Public Key ปกติ</a>',
	'ec_alipay_app_cert' => '(จำเป็น) RSA2(SHA256) ใบรับรอง Public Key ของแอป',
	'ec_alipay_app_cert_comment' => 'สำหรับรายละเอียดการรับใบรับรองคีย์สาธารณะ (Public Key Certificate) โปรดดูที่ <a href="https://opendocs.alipay.com/open/291/105971#%E5%85%AC%E9%92%A5%E8%AF%81%E4%B9%A6%E6%96%B9%E5%BC%8F" target="_blank">การรับใบรับรองคีย์สาธารณะ</a>; ไฟล์ appCertPublicKey_*.crt ให้ใช้โปรแกรม Notepad เปิดไฟล์นี้ จากนั้นคัดลอกเนื้อหาทั้งหมดมาวางที่นี่',
	'ec_alipay_alipay_cert' => '(จำเป็น) ใบรับรองคีย์สาธารณะ Alipay แบบ RSA2(SHA256)',
	'ec_alipay_alipay_cert_comment' => 'สำหรับรายละเอียดการรับใบรับรองคีย์สาธารณะ โปรดดูที่ <a href="https://opendocs.alipay.com/open/291/105971#%E5%85%AC%E9%92%A5%E8%AF%81%E4%B9%A6%E6%96%B9%E5%BC%8F" target="_blank">การรับใบรับรองคีย์สาธารณะ</a>; ไฟล์ alipayCertPublicKey_RSA2.crt ให้ใช้โปรแกรม Notepad เปิดไฟล์นี้ จากนั้นคัดลอกเนื้อหาทั้งหมดมาวางที่นี่',
	'ec_alipay_alipay_root_cert' => '(จำเป็น) ใบรับรองหลัก (Root Certificate) Alipay แบบ RSA2(SHA256)',
	'ec_alipay_alipay_root_cert_comment' => 'สำหรับรายละเอียดการรับใบรับรองคีย์สาธารณะ โปรดดูที่ <a href="https://opendocs.alipay.com/open/291/105971#%E5%85%AC%E9%92%A5%E8%AF%81%E4%B9%A6%E6%96%B9%E5%BC%8F" target="_blank">การรับใบรับรองคีย์สาธารณะ</a>; ไฟล์ alipayRootCert.crt ให้ใช้โปรแกรม Notepad เปิดไฟล์นี้ จากนั้นคัดลอกเนื้อหาทั้งหมดมาวางที่นี่',
	'ec_alipay_check' => 'ทดสอบการชำระเงิน',

	'ec_wechat' => 'ตั้งค่า WeChat Pay',
	'ec_wechat_tips' => '<li>WeChat Pay (https://pay.weixin.qq.com) เป็นแพลตฟอร์มการชำระเงินบุคคลที่สามชั้นนำของ Tencent มุ่งมั่นให้บริการที่ปลอดภัย สะดวก และเป็นมืออาชีพ</li><li><b>โปรดอ่านคู่มือการใช้งานอย่างละเอียดก่อนเริ่มตั้งค่าเพื่อป้องกันความสูญเสียด้านเงินทุน</b></li><li>การใช้บริการ WeChat Pay เป็นไปตามความสมัครใจของผู้ใช้เอง ทาง Tencent Cloud จะไม่รับผิดชอบต่อความสูญเสียใด ๆ ยกเว้นกรณีที่เป็นความผิดพลาดโดยเจตนาจากระบบ Discuz!</li><li>สายด่วนบริการลูกค้า WeChat Pay คือ 95017</li>',
