	'ec_wechat_v1_cert_comment' => 'ตำแหน่งไฟล์ใบรับรอง cert.p12 ใช้สำหรับการคืนเงิน หากไม่ทำรายการคืนเงินผ่านระบบสามารถเว้นว่างได้ ไฟล์ต้องอยู่ในไดเรกทอรีเว็บไซต์ เช่น source/data/{randomstr}.p12',
