	'ec_qpay' => 'ตั้งค่า QQ Wallet',
	'ec_qpay_tips' => '<li>QQ Wallet เป็นแพลตฟอร์มการชำระเงินภายใต้ Tenpay ของ Tencent</li><li><b>โปรดตั้งค่าข้อมูลการรับเงินให้ถูกต้อง เพื่อป้องกันปัญหาเครดิตไม่เข้าบัญชีผู้ใช้โดยอัตโนมัติ ซึ่งจะทำให้เกิดภาระในการตรวจสอบข้อมูลด้วยตนเองจำนวนมาก</b></li><li>สายด่วนบริการ Tenpay: 0755-83762288-2 หรืออีเมล qpay@tencent.com</li>',
