	'ec_qpay_mch_id_comment' => 'หมายเลขผู้ค้าที่ได้รับจาก QQ Wallet',
	'ec_qpay_op_user_id' => '(ไม่บังคับ) ไอดีผู้ดำเนินการ',
	'ec_qpay_op_user_id_comment' => 'ใช้สำหรับการคืนเงิน ค่าเริ่มต้นคือหมายเลขผู้ค้า',
	'ec_qpay_op_user_passwd' => '(ไม่บังคับ) รหัสผ่านผู้ดำเนินการ',
	'ec_qpay_op_user_passwd_comment' => 'ใช้สำหรับการคืนเงิน ระบบจะบันทึกในรูปแบบ md5',
	'ec_qpay_v1_key' => '(จำเป็น) คีย์ API',
	'ec_qpay_v1_key_comment' => 'จัดการได้ที่ QQ Wallet Merchant Platform --> Account Management --> API Security',
	'ec_qpay_v1_cert' => '(ไม่บังคับ) พาธใบรับรองการชำระเงิน',
	'ec_qpay_v1_cert_comment' => 'ตำแหน่งที่ตั้งของไฟล์ใบรับรอง cert.p12 แนะนำให้เปลี่ยนชื่อไฟล์เพื่อหลีกเลี่ยงการเข้าถึงไฟล์โดยตรง จำเป็นต้องใช้สำหรับการทำรายการคืนเงิน หากคุณไม่ต้องการใช้ระบบคืนเงินสามารถปล่อยว่างไว้ได้ โดยไฟล์จะต้องอยู่ในไดเรกทอรีของเว็บไซต์ เช่น source/data/{randomstr}.p12',
	'ec_qpay_check' => 'ทดสอบการชำระเงิน',
	'ec_qpay_checklink_credit' => 'ทดสอบการเติมเครดิต',

	'ec_orders' => 'รายการเติมเครดิต',
	'ec_orders_tips' => '<li>โปรดอ่านส่วนที่เกี่ยวกับพาณิชย์อิเล็กทรอนิกส์ใน "คู่มือการใช้งาน" อย่างละเอียด ก่อนเริ่มใช้งานฟังก์ชันการจัดการรายการสั่งซื้อแลกเครดิตของ Alipay (ไม่รวมฟังก์ชันปุ่ม Alipay) และดำเนินการเมื่อคุณมั่นใจว่าเข้าใจและยอมรับขั้นตอนรวมถึงวิธีการใช้งานที่เกี่ยวข้องอย่างครบถ้วนแล้วเท่านั้น</li><li>หากผู้ใช้แจ้งว่าระบบไม่เติมเครดิตเข้าบัญชีโดยอัตโนมัติหลังจากชำระเงินออนไลน์ อาจเกิดจากการตั้งค่าอินเทอร์เฟซการแจ้งเตือน (Notification Interface) ของบัญชี Alipay ผิดพลาด หรือเว็บไซต์ของคุณไม่สามารถเข้าถึงได้ตามปกติโดยระบบแจ้งเตือนของ Alipay คุณสามารถเข้าสู่หน้าการจัดการธุรกรรมของ Alipay เพื่อตรวจสอบและยืนยันรายการสั่งซื้อด้วยตนเองโดยการเปรียบเทียบรายละเอียดธุรกรรม</li><li>ข้อมูลคำสั่งซื้อจะถูกเก็บไว้เป็นเวลา 60 วัน ดังนั้นคุณจึงสามารถตรวจสอบและจัดการข้อมูลได้ภายในระยะเวลา 60 วันเท่านั้น ข้อมูลที่เก่ากว่า 60 วันจะถูกลบออกโดยอัตโนมัติ</li>',
