	'tools_updatecache_tips' => '<li>เมื่อมีการกู้คืนข้อมูล, อัปเกรดระบบ หรือพบการทำงานที่ผิดปกติ คุณสามารถใช้ฟังก์ชันนี้เพื่อสร้างไฟล์แคชใหม่ การอัปเดตแคชอาจทำให้ภาระของเซิร์ฟเวอร์สูงขึ้น โปรดหลีกเลี่ยงช่วงเวลาที่มีผู้ใช้งานหนาแน่น</li>
