				<li>แคชที่เก็บข้อมูลออบเจกต์ (OSS): เมื่อเปิดใช้งาน OSS จะเป็นการอัปเดตไฟล์สเตติก เช่น CSS, JS ไปยังที่เก็บข้อมูลออบเจกต์</li>
				<li>แคชหมวดหมู่มอดูล DIY: อัปเดตหมวดหมู่ของมอดูล DIY ใช้เมื่อคุณติดตั้งหรือแก้ไขหมวดหมู่แล้วไม่เห็นผลทันที</li>
				<li>แคช CSS: อัปเดตไฟล์ CSS ของเทมเพลตและสไตล์ ใช้เมื่อมีการแก้ไข CSS ของสไตล์แล้วระบบไม่อัปเดต</li>
