	'db_delete_tips' => '<br /><br /><a href="'.ADMINSCRIPT.'?action=db&operation=import&deletesubmit=1&delete[]={filename}&formhash={FORMHASH}" onclick="return confirm(\'คุณยืนยันที่จะลบไฟล์สำรองข้อมูลออกจากเซิร์ฟเวอร์หรือไม่\');"><font color="#fe7e01"><strong>ลบไฟล์สำรองข้อมูลบนเซิร์ฟเวอร์</strong></font></a>',
	'db_export_tips_nouc' => '<li><font color="blue"><b>การสำรองข้อมูลปัจจุบันของคุณไม่รวม UCenter ซึ่งจะส่งผลกระทบต่อข้อมูลสมาชิก โปรดคลิก<a href="{uc_backup_url}">ที่นี่</a>เพื่อสำรองข้อมูล UCenter แยกต่างหาก</b></font></li><li>ฟังก์ชันสำรองข้อมูลจะสำรองข้อมูลทั้งหมดของ Discuz! ตามที่คุณเลือก ไฟล์ข้อมูลที่ส่งออกสามารถนำไปใช้ในฟังก์ชัน “คืนค่าข้อมูล” หรือนำเข้าผ่าน phpMyAdmin ได้</li>',
	'db_export_tips_uc' => '<li>ฟังก์ชันสำรองข้อมูลจะสำรองข้อมูลทั้งหมดของ Discuz! และ UCenter ตามที่คุณเลือก ไฟล์ข้อมูลที่ส่งออกสามารถนำไปใช้ในฟังก์ชัน “คืนค่าข้อมูล” หรือนำเข้าผ่าน phpMyAdmin ได้</li>',
	'db_export_tips' => '<li><font color="blue"><b>เพื่อความปลอดภัย เราขอแนะนำอย่างยิ่งให้คุณดาวน์โหลดไฟล์สำรองข้อมูลเก็บไว้แล้วลบไฟล์ออกจากเซิร์ฟเวอร์ หรือตั้งค่าไม่ให้เข้าถึงไฟล์ผ่าน URL ได้</b></font></li><li>การสำรองข้อมูลทั้งหมดไม่รวมไฟล์เทมเพลตและไฟล์แนบ คุณสามารถสำรองข้อมูลเหล่านั้นได้โดยการดาวน์โหลดไดเรกทอรี template/ และ data/attachment/ ผ่าน FTP ฯลฯ โดย Discuz! จะไม่มีฟังก์ชันสำรองส่วนนี้แยกต่างหาก</li><li>การตั้งค่าในตัวเลือกการสำรองข้อมูลมีไว้สำหรับผู้ใช้งานระดับสูงเพื่อวัตถุประสงค์พิเศษเท่านั้น หากคุณยังไม่มีความเข้าใจในฐานข้อมูลอย่างละเอียดถี่ถ้วน โปรดใช้พารามิเตอร์เริ่มต้นในการสำรองข้อมูล มิฉะนั้นอาจทำให้ข้อมูลสำรองผิดพลาดหรือเกิดปัญหาร้ายแรงได้</li><li>รูปแบบเลขฐานสิบหก (Hexadecimal) จะช่วยรับประกันความสมบูรณ์ของข้อมูลได้ดีกว่า แต่ไฟล์สำรองจะมีขนาดใหญ่ขึ้น</li><li>การบีบอัดไฟล์จะช่วยให้ไฟล์สำรองข้อมูลของคุณใช้พื้นที่น้อยลง</li><li>สำหรับการคืนค่าข้อมูล โปรดใช้เครื่องมือที่มาพร้อมกับตัวติดตั้ง Discuz! (เข้าถึงโดยการเปลี่ยนชื่อไฟล์ install/index.php ก่อนใช้งาน)</li>',
