	'db_runquery_tips' => '<li>คุณสามารถเพิ่มคำสั่ง SQL ที่ใช้งานบ่อยได้โดยการแก้ไขไฟล์ /source/admincp/admincp_quickquery.php เพื่อเพิ่มฟังก์ชันการทำงาน</li><li>เพื่อความปลอดภัย ระบบหลังบ้านของ Discuz! จะไม่อนุญาตให้รันคำสั่ง SQL โดยตรงเป็นค่าเริ่มต้น และจะให้ใช้ได้เฉพาะคำสั่งสำเร็จรูปที่มีอยู่เท่านั้น <br />หากคุณต้องการเขียนคำสั่ง SQL เพื่ออัปเกรดเอง คุณต้องแก้ไขค่า $_config[\'admincp\'][\'runquery\'] ในไฟล์ config/config_global.php ให้เป็น 1</li>',
