	'adv_type_headerbanner' => 'โฆษณาแบนเนอร์ส่วนหัว',
	'adv_type_headerbanner_tips' => '<li>รูปแบบการแสดงผล: โฆษณาแบนเนอร์ส่วนหัวจะแสดงที่ด้านบนขวาของหน้าเว็บบอร์ด โดยปกติจะใช้รูปภาพขนาด 468x60 หรือไฟล์ Flash หากมีโฆษณาหลายรายการในหน้าเดียวกัน ระบบจะสุ่มเลือกรายการใดรายการหนึ่งขึ้นมาแสดง</li><li>วิเคราะห์ความคุ้มค่า: เนื่องจากเป็นตำแหน่งที่สะดุดตาที่สุดทันทีที่เปิดหน้าเว็บ จึงเป็นหนึ่งในประเภทโฆษณาที่มีราคาสูงที่สุด และเหมาะที่สุดสำหรับการสื่อสารเชิงพาณิชย์หรือการสร้างแบรนด์</li>',
	'adv_type_footerbanner' => 'โฆษณาแบนเนอร์ส่วนท้าย',
	'adv_type_footerbanner_tips' => '<li>รูปแบบการแสดงผล: โฆษณาแบนเนอร์ส่วนท้ายจะแสดงที่ด้านล่างตรงกลางของหน้าเว็บบอร์ด โดยปกติจะใช้รูปภาพขนาด 468x60 หรือขนาดอื่น ๆ รวมถึงไฟล์ Flash หากมีหลายรายการ ระบบจะสุ่มเลือกขึ้นมาแสดง</li><li>วิเคราะห์ความคุ้มค่า: เมื่อเทียบกับส่วนหัวและส่วนกลาง อัตราการเห็นโฆษณาส่วนท้ายจะต่ำกว่าเล็กน้อย แต่ปกติจะไม่สร้างความรำคาญให้ผู้เข้าชม ในขณะที่ยังสามารถครอบคลุมกลุ่มเป้าหมายที่สนใจเนื้อหาจริง ๆ ได้ดี เหมาะสำหรับการโปรโมตแบบนุ่มนวล</li>',
	'adv_type_text' => 'โฆษณาข้อความในหน้าเพจ',
	'adv_type_text_tips' => '<li>รูปแบบการแสดงผล: โฆษณาข้อความจะแสดงเป็นตารางที่ส่วนบนของหน้าแรก, หน้ารายการกระทู้ และหน้าเนื้อหาโพสต์ โดยปกติจะใช้ข้อความ หรือรูปภาพขนาดเล็กและ Flash หากมีหลายรายการ ระบบจะแสดงทั้งหมดตามลำดับที่ตั้งไว้ และปรับจำนวนคอลัมน์ให้อัตโนมัติ (3 - 5 คอลัมน์) เพื่อความสวยงาม</li><li>วิเคราะห์ความคุ้มค่า: แม้จะเป็นเพียงข้อความ แต่ตำแหน่งที่อยู่ค่อนข้างสูงทำให้เป็นสิ่งที่ผู้เข้าชมมักจะต้องอ่าน การที่แสดงผลได้นับสิบรายการพร้อมกันทำให้เป็นรูปแบบการโปรโมตที่เข้าถึงง่ายและคุ้มค่ามาก รวมถึงใช้เป็นพื้นที่ประชาสัมพันธ์ของเว็บบอร์ดเองได้ด้วย</li>',
	'adv_type_thread' => 'โฆษณาภายในโพสต์',
	'adv_type_thread_tips' => '<li>รูปแบบการแสดงผล: จะแสดงที่ด้านบน, ด้านล่าง หรือด้านขวาของเนื้อหาโพสต์ โดยส่วนบนและล่างมักใช้ข้อความ ส่วนด้านขวามักใช้รูปภาพ ระบบจะสุ่มโฆษณาขึ้นมาแสดงตามจำนวนโพสต์ต่อหน้า คุณสามารถตั้งค่าจำนวนโฆษณาที่จะแสดงต่อโพสต์ได้ที่เมนูตั้งค่าส่วนกลาง</li><li>วิเคราะห์ความคุ้มค่า: เนื่องจากโพสต์คือหัวใจสำคัญของเว็บบอร์ด โฆษณาที่แทรกอยู่ในเนื้อหาจะถูกผู้ใช้งานมองเห็นอย่างเป็นธรรมชาติขณะอ่านกระทู้ เหมาะสำหรับการโปรโมตเฉพาะเจาะจง และควรตั้งค่าโฆษณาให้มีความหลากหลายเพื่อดึงดูดความสนใจ</li>',
	'adv_type_interthread' => 'โฆษณาแบนเนอร์ระหว่างโพสต์',
	'adv_type_interthread_tips' => '<li>รูปแบบการแสดงผล: แสดงระหว่างกระทู้หลักและโพสต์ตอบกลับแรก สามารถใช้รูปภาพหรือ Flash ขนาด 468x60 หรือขนาดอื่น ๆ หากมีหลายรายการ ระบบจะสุ่มแสดงรายการใดรายการหนึ่ง</li><li>วิเคราะห์ความคุ้มค่า: ด้วยการวางตำแหน่งคั่นกลางระหว่างเนื้อหาหลักกับความเห็น ทำให้มีขนาดแบนเนอร์ที่ใหญ่แต่ไม่รบกวนการอ่านเนื้อหา จึงไม่สร้างความรำคาญแก่เจ้าของกระทู้และผู้เข้าชม เหมาะสำหรับการโฆษณาเชิงธุรกิจหรือแบรนด์สินค้า</li>',
	'adv_type_float' => 'โฆษณาแบบลอย',
	'adv_type_float_tips' => '<li>รูปแบบการแสดงผล: จะแสดงที่มุมล่างซ้ายของหน้าจอ และเคลื่อนที่ตามการเลื่อนหน้าเว็บ (Scroll) เพื่อรักษาตำแหน่งเดิมไว้เสมอ มักใช้รูปภาพขนาดเล็กหรือ Flash หากมีหลายรายการ ระบบจะสุ่มแสดงรายการใดรายการหนึ่ง</li><li>วิเคราะห์ความคุ้มค่า: เป็นเครื่องมือที่มีประสิทธิภาพในการดึงดูดความสนใจอย่างมาก เนื่องจากความสามารถในการเคลื่อนไหวที่เด่นกว่ารูปภาพนิ่ง แต่ในทางกลับกันก็อาจสร้างความรำคาญให้ผู้ที่ไม่ได้สนใจเนื้อหานั้นได้ โปรดระวังอย่าใช้รูปภาพที่มีขนาดใหญ่เกินไปจนบดบังการอ่านเนื้อหาหลัก</li>',
	'adv_type_couplebanner' => 'โฆษณาแบบคู่ (ซ้าย-ขวา)',
	'adv_type_couplebanner_tips' => '<li>รูปแบบการแสดงผล: แสดงเป็นรูปภาพแนวตั้งสองฝั่งที่ด้านบนของหน้าเว็บ คล้ายกับคำกลอนคู่ มักใช้รูปภาพแนวสูงที่มีความกว้างไม่มาก เหมาะสำหรับเว็บไซต์ที่กำหนดความกว้างตารางหลักเป็นพิกเซล หากใช้ความกว้างแบบเปอร์เซ็นต์ (เกิน 90%) อาจรบกวนการใช้งานได้ ทั้งนี้โฆษณานี้จะไม่แสดงหากหน้าจอเบราว์เซอร์กว้างน้อยกว่า 800 พิกเซล</li><li>วิเคราะห์ความคุ้มค่า: เนื่องจากแสดงเฉพาะในหน้าจอความละเอียดสูง (1024x768 ขึ้นไป) และใช้พื้นที่ว่างด้านข้าง จึงโดดเด่นมากโดยไม่รบกวนการอ่านเนื้อหา แต่อาจเข้าถึงกลุ่มผู้ใช้งานได้ไม่ครอบคลุม 100% เนื่องจากข้อจำกัดด้านความละเอียดหน้าจอ</li>',
	'adv_type_intercat' => 'โฆษณาระหว่างหมวดหมู่',
	'adv_type_intercat_tips' => '<li>รูปแบบการแสดงผล: แสดงคั่นระหว่างหมวดหมู่เว็บบอร์ดสองหมวดที่อยู่ติดกันในหน้าแรก สามารถใช้รูปภาพหรือ Flash ขนาด 468x60 หรือขนาดอื่น ๆ ระบบจะสุ่มเลือกโฆษณาขึ้นมาแสดงตามจำนวนหมวดหมู่ที่มี</li><li>วิเคราะห์ความคุ้มค่า: ปรากฏในตำแหน่งที่เห็นชัดเจนในหน้าแรกของเว็บบอร์ด ทำให้มีประสิทธิภาพในการแสดงผลดีเยี่ยม แต่ควรระวังอย่าให้มีขนาดใหญ่หรือจำนวนมากเกินไปจนทำให้หน้าแรกดูไม่สบายตา</li>',
