	'adv_list_tip' => '<li>คุณสามารถใช้ “ตำแหน่งโฆษณากำหนดเอง” เพื่อแทรกโฆษณาในจุดใดก็ได้ของหน้าเพจ</li><li>ตำแหน่งโฆษณาของระบบอยู่ที่ source/class/adv/ และของปลั๊กอินอยู่ที่ source/plugin/ชื่อปลั๊กอิน/adv/</li><li>นักพัฒนาโปรดอ่าน “<a href="https://open.dismall.com/?!devdoc" target="_blank">เอกสารทางเทคนิค Discuz!</a>” ก่อนออกแบบตำแหน่งโฆษณาใหม่</li><li>สามารถเพิ่มตำแหน่งโฆษณากำหนดเองแบบไดนามิกได้โดยใส่รหัส &lt;!--{ad/addon_*}--&gt; ในไฟล์เทมเพลต</li>',
