	'diytemplate' => 'จัดการหน้าเพจ',
	'diytemplate_perm_tips' => '<li>สิทธิ์การใช้งานที่ตั้งค่าที่นี่จะมีผลกับมอดูล DIY ทั้งหมดในหน้านี้ (ยกเว้นมอดูลที่ตั้งค่าไม่ให้สืบทอดสิทธิ์จากหน้าเพจ)</li><li>การกำหนดว่ามอดูลจะสืบทอดสิทธิ์หรือไม่ สามารถตั้งค่าได้ที่ “จัดการมอดูล” => “สิทธิ์การจัดการ”</li><li>1. สิทธิ์ของมอดูลมีความสำคัญสูงกว่าสิทธิ์ของหน้าเพจ; 2. สิทธิ์ "อนุญาตให้จัดการ" หมายถึงจัดการได้ทั้งคุณสมบัติและข้อมูลของมอดูล; <br />3. สิทธิ์ "อนุญาตให้พุช" และไม่ใช่ "ต้องคัดกรองการพุช" สามารถจัดการข้อมูลมอดูลได้; 4. สิทธิ์ "อนุญาตให้พุช" และ "ต้องคัดกรองการพุช" สามารถส่งข้อมูลได้แต่ไม่สามารถจัดการมอดูลได้</li>',
