	'blockstyle_add_tips' => '<li>คุณสามารถใช้แท็ก [loop]...[/loop] เพื่อวนลูปแสดงผลข้อมูลในมอดูล หากต้องการวนลูปหลายที่ในเทมเพลตเดียว สามารถใช้ [loop1]...[/loop1] (ขยายได้สูงสุด 1-9 รายการ)</li><li>คุณสามารถใช้แท็ก [order=N]...[/order] เพื่อกำหนดการแสดงผลข้อมูลในตำแหน่งที่ N แทนค่าเริ่มต้นใน loop (ใช้ [order1=N] สำหรับ [loop1])</li><li>คุณสามารถใช้ [index=N]...[/index] เพื่อระบุรูปแบบการแสดงผลเฉพาะของข้อมูลลำดับที่ N ซึ่งข้อมูลที่ระบุนี้จะไม่ปรากฏใน loop ปกติอีก และสามารถใช้ [index1] ขยายเพื่อแสดงข้อมูลเดียวกันในหลายตำแหน่งได้</li><li>คุณสามารถใช้แท็กรูปภาพที่รองรับการสร้างรูปย่อ (Thumbnail) หรือลิงก์ที่ระบุวิธีเปิดหน้าต่างได้</li><li>บางมอดูล (เช่น มอดูลสเตติก) เนื้อหาจะถูกสร้างจากแหล่งข้อมูลโดยตรง จึงไม่จำเป็นต้องใช้เทมเพลต</li><li>ฟิลด์ข้อมูล (เช่น {title}) จะมีผลเฉพาะเมื่ออยู่ภายในแท็ก [loop], [order] หรือ [index] เท่านั้น</li>',
