	'rewrite_message' => '<h1>Apache Web Server (สำหรับผู้ใช้ VPS หรือเซิร์ฟเวอร์ส่วนตัว)</h1>
<pre class="colorbox">
&lt;IfModule mod_rewrite.c&gt;
	RewriteEngine On
{apache1}&lt;/IfModule&gt;
</pre>

<h1>Apache Web Server (สำหรับผู้ใช้โฮสติ้งทั่วไป)</h1>
<pre class="colorbox">
# เปิดโหมด RewriteEngine
RewriteEngine On

# ตัวอย่างเช่น www.discuz.vip/bbs/ ให้ใช้ RewriteBase /bbs/ หากติดตั้งในไดเรกทอรีหลัก ให้ใช้ RewriteBase /
RewriteBase {siteroot}

# ห้ามแก้ไขกฎของระบบด้านล่างนี้
{apache2}
</pre>

<h1>Nginx Web Server</h1>
<pre class="colorbox">
{nginx}
</pre>

<h1>IIS Web Server (สำหรับผู้ใช้ VPS หรือเซิร์ฟเวอร์ส่วนตัว)</h1>
<pre class="colorbox">
[ISAPI_Rewrite]

# 3600 = 1 ชั่วโมง
CacheClockRate 3600

RepeatLimit 32

# ป้องกันการเข้าถึงไฟล์ httpd.ini และ httpd.parse.errors 
# ผ่านโปรโตคอล HTTP
{iis}
</pre>

<h1>IIS7 Web Server (สำหรับผู้ใช้ VPS หรือเซิร์ฟเวอร์ส่วนตัว)</h1>
<pre class="colorbox">
&lt;rewrite&gt;
	&lt;rules&gt;
{iis7}	&lt;/rules&gt;
&lt;/rewrite&gt;
</pre>

<h1>Lighttpd Web Server</h1>
<pre class="colorbox">
url.rewrite-once = (
{lighttpd})
</pre>

<h1>Caddy Web Server</h1>
<pre class="colorbox">
{caddy}
</pre>',

