	'account_detail' => 'รายละเอียดบัญชีที่ผูกไว้',
	'account_basesetting_tips' => '<li>ก่อนเปิดใช้งานการล็อกอินอัตโนมัติหรือการโอนสิทธิ์ล็อกอิน/ลงทะเบียนสมาชิก โปรดผูกบัญชีบุคคลที่สามให้เรียบร้อยก่อน เพื่อป้องกันไม่ให้บัญชีผู้ดูแลระบบเข้าสู่ระบบหลังบ้านไม่ได้</li>
		<li>ล็อกอินอัตโนมัติ (ค่าเริ่มต้น): เมื่อเปิดใช้งาน การล็อกอินในสถานะผู้เข้าชมทั้งหมดจะถูกส่งไปยังการล็อกอินผ่านบุคคลที่สามที่ระบุ และการล็อกอินแบบปกติจะถูกปิดใช้งาน</li>
		<li>ล็อกอินอัตโนมัติ (ตามสภาพแวดล้อม): เมื่อเปิดใช้งาน จะล็อกอินอัตโนมัติเมื่ออยู่ในสภาพแวดล้อมของบุคคลที่สามที่เกี่ยวข้อง</li>
		<li>ล็อกอินด้วยตนเอง: เมื่อเปิดใช้งาน จะมีการเพิ่มปุ่มเข้าสู่ระบบในส่วน "วิธีเข้าสู่ระบบอื่น ๆ" ในหน้าล็อกอิน</li>
		<li>โอนสิทธิ์ล็อกอิน/ลงทะเบียนสมาชิก (ค่าเริ่มต้น): เมื่อเปิดใช้งาน การคลิกปุ่ม "ล็อกอิน/ลงทะเบียนสมาชิก" จะส่งไปยังการล็อกอินผ่านบุคคลที่สามที่ระบุ และการล็อกอินแบบปกติจะถูกปิดใช้งาน</li>
		<li>โอนสิทธิ์ล็อกอิน/ลงทะเบียนสมาชิก (ตามสภาพแวดล้อม): เมื่อเปิดใช้งาน การคลิกปุ่ม "ล็อกอิน/ลงทะเบียนสมาชิก" จะเปลี่ยนเส้นทางและล็อกอินอัตโนมัติตามสภาพแวดล้อมปัจจุบัน</li>
		<li>อนุญาตให้ผู้ใช้ใหม่ล็อกอิน: เปิดใช้งานเป็นค่าเริ่มต้น หากปิดใช้งาน จะไม่มีการลงทะเบียนผู้ใช้ใหม่ผ่านช่องทางนี้</li>',
