	'qrcodelogin_tips' => '<li>ฟังก์ชันนี้เป็นบริการคลาวด์จาก WitFrame ผู้ใช้สามารถสแกนคิวอาร์โค้ดผ่าน WeChat เพื่อเข้าสู่ระบบหลังบ้านโดยไม่ต้องกรอกรหัสผ่าน</li><li>การใช้งานครั้งแรกจำเป็นต้องตั้งค่า “รหัสผ่านผูกบัญชี” หากมีผู้ดูแลหลายคน ให้แจ้งรหัสนี้แก่ผู้ดูแลท่านอื่นด้วย</li><li>ผู้ใช้งานในสถานะ “ผู้ก่อตั้ง” จะได้รับการแจ้งเตือนการล็อกอินผ่านบัญชีทางการของ Discuz! หากได้ติดตามไว้</li><li>หากผู้ใช้ที่มีการผูกบัญชีไว้แล้วทำการเปลี่ยนรหัสผ่าน จำเป็นต้องผูกบัญชีใหม่อีกครั้ง</li><li>หากไม่ต้องการใช้ฟังก์ชันนี้ สามารถปิดการใช้งานและล้างข้อมูลได้ในหน้าตั้งค่า</li>',
